local tbl = 
{
	
	{
		data = 
		{
			actions = 
			{
				
				{
					data = 
					{
						aType = "Lua",
						actionLua = "-- ============================================================\n-- Rikuduo's Gadget\n-- 借鉴自 LJ Toolbox（原 \"LJ Toolbox KAI\"）：工具按钮、状态检测与 Map Effects Explorer\n-- 均参考 LJ Toolbox 的实现，在此基础上整合了 Rikuduo's Gadget 的职业选择与 UI 风格。\n-- ============================================================\n-- --------------------------\n-- GUI FLAGS（有标题栏/可折叠）\n-- --------------------------\nlocal GUI_FLAGS = GUI.WindowFlags_AlwaysAutoResize + GUI.WindowFlags_NoScrollbar\nlocal BTN_WIDTH, BTN_HEIGHT = 95, 20\nlocal PICK_W, PICK_H = 155, 18\n\n-- popup ids\nlocal POP_ROLE  = \"PopupRole##RG\"\nlocal POP_GROUP = \"PopupGroup##RG\"\nlocal POP_HEAL  = \"PopupHealer##RG\"\nlocal POP_DPS   = \"PopupDps##RG\"\n\n-- --------------------------\n-- LJ-style button colors (for our selectors)\n-- --------------------------\nlocal ROLE_COLORS = {\n  tank   = {0.2, 0.4, 0.8, 1.0}, -- blue\n  healer = {0.2, 0.5, 0.2, 1.0}, -- green\n  dps    = {0.7, 0.2, 0.2, 1.0}, -- red\n}\n\nlocal function PushRoleButtonColor(roleKey)\n  local c = ROLE_COLORS[roleKey]\n  if not c then return 0 end\n  GUI:PushStyleColor(GUI.Col_Button,        c[1], c[2], c[3], c[4])\n  GUI:PushStyleColor(GUI.Col_ButtonHovered, math.min(c[1]+0.08,1), math.min(c[2]+0.08,1), math.min(c[3]+0.08,1), c[4])\n  GUI:PushStyleColor(GUI.Col_ButtonActive,  math.max(c[1]-0.08,0), math.max(c[2]-0.08,0), math.max(c[3]-0.08,0), c[4])\n  return 3\nend\n\n-- --------------------------\n-- Job helpers\n-- --------------------------\nlocal function _getJob()\n  if not TensorCore or not TensorCore.mGetPlayer then return 0 end\n  local p = TensorCore.mGetPlayer()\n  return (p and p.job) or 0\nend\n\nlocal function _isTankJob(job)\n  job = job or _getJob()\n  return (job == 19 or job == 21 or job == 32 or job == 37) -- PLD/WAR/DRK/GNB\nend\n\nlocal function _isHealerJob(job)\n  job = job or _getJob()\n  return (job == 24 or job == 28 or job == 33 or job == 40) -- WHM/SCH/AST/SGE\nend\n\n-- ✅ DPS 白名单（避免采集/生产）\nlocal function _isAnyDpsJob(job)\n  job = job or _getJob()\n  return (\n    job == 34 or job == 20 or job == 30 or job == 22 or job == 39 or job == 41 or -- SAM/MNK/NIN/DRG/RPR/VPR\n    job == 23 or job == 31 or job == 38 or job == 27 or job == 25 or job == 42    -- BRD/MCH/DNC/SMN/BLM/PCT\n  )\nend\n\n-- Group label mapping (UI only)\nlocal GROUP_LABEL = { MTgroup=\"MT\", STgroup=\"ST\", Manualgroup=\"Manual\" }\nlocal function GroupDisplay(v) return GROUP_LABEL[v] or v end\n\n-- ============================================================\n-- Shared Store (portable)\n-- ============================================================\nlocal SAVE_DIR  = GetLuaModsPath() .. [[TensorReactions\\GeneralReactions\\Rikuduo_s_Gadgets\\Settings]]\nlocal SAVE_FILE = SAVE_DIR .. [[\\SelectionDR.lua]]\n\nlocal function _ensure_dir_tree(path)\n  if not FolderExists(path) then\n    local acc = \"\"\n    for part in string.gmatch(path, [[[^\\\\]+]]) do\n      acc = (acc == \"\") and part or (acc .. [[\\]] .. part)\n      if not FolderExists(acc) then FolderCreate(acc) end\n    end\n  end\nend\n\n_G.RikuduoGadget = _G.RikuduoGadget or {}\nlocal RG = _G.RikuduoGadget\nRG.__store = RG.__store or { loaded=false, data=nil }\n\nlocal function _load_store()\n  if RG.__store.loaded then return end\n  local ok, data = pcall(FileLoad, SAVE_FILE)\n  if ok and type(data) == \"table\" then\n    -- legacy：顶层 state/order -> SelectionDR\n    if data.state and data.order and (not data.SelectionDR) then\n      data = { SelectionDR = { state=data.state, order=data.order } }\n    end\n    RG.__store.data = data\n  else\n    RG.__store.data = {}\n  end\n  RG.__store.loaded = true\nend\n\nlocal function _save_store()\n  _ensure_dir_tree(SAVE_DIR)\n  FileSave(SAVE_FILE, RG.__store.data)\nend\n\nlocal function _ensure_node(name, order, stateDefault)\n  local d = RG.__store.data\n  d[name] = d[name] or { order=order, state=stateDefault }\n  d[name].order = d[name].order or order\n  d[name].state = d[name].state or stateDefault\n\n  for _,k in ipairs(order) do\n    if type(d[name].state[k]) ~= \"boolean\" then\n      d[name].state[k] = (k == order[1])\n    end\n    local found=false\n    for __,v in ipairs(d[name].order) do if v==k then found=true end end\n    if not found then table.insert(d[name].order, k) end\n  end\nend\n\nlocal function _ensure_all_nodes()\n  _load_store()\n\n  _ensure_node(\"SelectionDR\", {\"MT\",\"ST\",\"Manual\"}, { MT=true, ST=false, Manual=false })\n  _ensure_node(\"GroupMit\", {\"MTgroup\",\"STgroup\",\"Manualgroup\"}, { MTgroup=true, STgroup=false, Manualgroup=false })\n  _ensure_node(\"HealerRole\", {\"H1\",\"H2\",\"Manual\"}, { H1=true, H2=false, Manual=false })\n  _ensure_node(\"DpsPanel\", {\"D1\",\"D2\",\"D3\",\"D4\",\"Manual\"}, { D1=true, D2=false, D3=false, D4=false, Manual=false })\n\n  RG.__store.data.SwitchUI = RG.__store.data.SwitchUI or { showSwitch=true, onlyInInstance=false }\n  if type(RG.__store.data.SwitchUI.showSwitch) ~= \"boolean\" then\n    RG.__store.data.SwitchUI.showSwitch = true\n  end\n  if type(RG.__store.data.SwitchUI.onlyInInstance) ~= \"boolean\" then\n    RG.__store.data.SwitchUI.onlyInInstance = false\n  end\nend\n\nlocal function _getSelected(nodeName, fallback)\n  _ensure_all_nodes()\n  local node = RG.__store.data[nodeName]\n  if not node then return fallback end\n  for _,name in ipairs(node.order) do\n    if node.state[name] then return name end\n  end\n  return fallback\nend\n\nlocal function _setSelected(nodeName, name)\n  _ensure_all_nodes()\n  local node = RG.__store.data[nodeName]\n  if not node or node.state[name] == nil then return false end\n  for k,_ in pairs(node.state) do node.state[k] = (k == name) end\n  _save_store()\n  return true\nend\n\n-- ============================================================\n-- RikuduoGadget API (Timeline/Condition)\n-- ============================================================\nRG.GetSelectionDR = RG.GetSelectionDR or function() return _getSelected(\"SelectionDR\",\"MT\") end\nRG.SetSelectionDR = RG.SetSelectionDR or function(name) return _setSelected(\"SelectionDR\", name) end\nRG.is = RG.is or function(name) return RG.GetSelectionDR() == name end\n\nRG.GetGroupMit = RG.GetGroupMit or function() return _getSelected(\"GroupMit\",\"MTgroup\") end\nRG.SetGroupMit = RG.SetGroupMit or function(name) return _setSelected(\"GroupMit\", name) end\nRG.group_is = RG.group_is or function(name) return RG.GetGroupMit() == name end\n\nRG.GetHealerRole = RG.GetHealerRole or function() return _getSelected(\"HealerRole\",\"H1\") end\nRG.SetHealerRole = RG.SetHealerRole or function(name) return _setSelected(\"HealerRole\", name) end\nRG.healer_is = RG.healer_is or function(name) return RG.GetHealerRole() == name end\n\nRG.GetDps = RG.GetDps or function() return _getSelected(\"DpsPanel\",\"D1\") end\nRG.SetDps = RG.SetDps or function(name) return _setSelected(\"DpsPanel\", name) end\nRG.dps_is = RG.dps_is or function(name) return RG.GetDps() == name end\n\n-- show switch + only in instance\nRG.ShowSwitchEnabled = RG.ShowSwitchEnabled or function()\n  _ensure_all_nodes()\n  local sw = RG.__store.data.SwitchUI\n  if not sw or sw.showSwitch ~= true then return false end\n  if sw.onlyInInstance == true then\n    if type(InInstance) == \"function\" then return InInstance() == true end\n    return false\n  end\n  return true\nend\nRG.show_switch = RG.show_switch or function() return RG.ShowSwitchEnabled() end\n\n-- ============================================================\n-- Status + Buttons + MapEffects Cache (LJ style but stored in RG)\n-- ============================================================\nRG.Settings = RG.Settings or {\n  showEffectTester = false,\n  searchFilter = \"\",\n  selectedIndex = -1\n}\nRG.State = RG.State or { mapEffectsCache = {} }\n\n-- only compute these once\nif not RG.Status then\n  local currentPID = GetCurrentPID()\n  local handle = io.popen(string.format('tasklist /M /FI \"PID eq %d\" /FO CSV', currentPID))\n  local hasDalamud = false\n  if handle then\n    local result = handle:read(\"*a\")\n    handle:close()\n    hasDalamud = result:match(\"Dalamud%.dll\") ~= nil\n  end\n  RG.Status = { dalamud = hasDalamud, optifine = (Optifine ~= nil) }\nend\n\nRG.DrawStatus = RG.DrawStatus or function(label, isActive)\n  GUI:Text(label .. \":\")\n  GUI:SameLine()\n  GUI:TextColored(isActive and 0 or 1, isActive and 1 or 0, 0, 1, isActive and \"YES\" or \"NO\")\nend\n\nRG.RefreshMapEffects = RG.RefreshMapEffects or function()\n  local cache = {}\n  local typeNames = { [2]=\"Model\", [4]=\"VFX\", [6]=\"Script\", [7]=\"Sound\" }\n\n  if Argus and Argus.getNumCurrentMapEffects then\n    local numEffects = Argus.getNumCurrentMapEffects()\n    for i = 0, numEffects - 1 do\n      local res = Argus.getMapEffectResource(i)\n      if res then\n        local resId, resPath, resType, isActive = Argus.getEffectResourceInfo(res)\n        local typeStr = typeNames[resType] or tostring(resType)\n\n        local validScriptCount = 0\n        if resType == 6 then\n          local rawNum = Argus.getNumEffectResourceScripts(res) or 0\n          for si = 0, rawNum - 1 do\n            local sName = Argus.getEffectResourceScriptInfo(res, si)\n            if sName and sName ~= \"\" then validScriptCount = validScriptCount + 1 end\n          end\n        end\n\n        local fullSearchString = string.format(\n          \"index=%d id=%d type=%s active=%s scripts=%d path=%s\",\n          i, resId or 0, typeStr, tostring(isActive), validScriptCount, tostring(resPath)\n        )\n\n        local shortPath = type(resPath) == \"string\" and (resPath:match(\".*/(.*)\") or resPath) or \"Unknown\"\n        local activeTag = isActive and \" (ON)\" or \"\"\n        local displayLabel = string.format(\"[%d] %s%s\", i, shortPath, activeTag)\n\n        table.insert(cache, {\n          index = i,\n          label = displayLabel,\n          searchString = string.lower(fullSearchString),\n          isActive = isActive\n        })\n      end\n    end\n  end\n\n  RG.State.mapEffectsCache = cache\nend\n\nRG.Buttons = RG.Buttons or {\n  { \"Reactions\", function() if AnyoneCore then AnyoneCore.openTensorReactions() end end },\n  { \"Dev Monitor\", function() if AnyoneCore then AnyoneCore.Settings.DevMonitor = not AnyoneCore.Settings.DevMonitor end end },\n  { \"ACR Options\", function() if ACR and ACR.OpenProfileOptions then ACR.OpenProfileOptions() end end },\n  { \"Effects Debug\", function()\n      RG.Settings.showEffectTester = not RG.Settings.showEffectTester\n      if RG.Settings.showEffectTester then RG.RefreshMapEffects() end\n    end\n  }\n}\n\n-- Console：GUI:ShowConsole 需要在打开期间每帧调用，按钮只切换开关\nRG.Settings.showConsole = (RG.Settings.showConsole == true)\ndo\n  local hasConsole = false\n  for _, b in ipairs(RG.Buttons) do\n    if b[1] == \"Console\" then hasConsole = true end\n  end\n  if not hasConsole then\n    table.insert(RG.Buttons, { \"Console\", function() RG.Settings.showConsole = not RG.Settings.showConsole end })\n  end\nend\n\n-- ============================================================\n-- MAIN TOOLBOX GUI — 紧凑面板：职位分配是主角，工具默认收起（标题栏右侧箭头展开）\n-- 颜色语法与 [Role] Mit Control 一致：绿 = 已选 / 已开启，灰 = 未选 / 关闭\n-- 右键窗口任意位置：缩放、边框、透明度、锁定、隐藏职位分配（设置存 ToolboxUI 节点）\n-- ============================================================\nlocal TB_GREEN  = { 0.18, 0.49, 0.31, 1.0 }\nlocal TB_GREENH = { 0.22, 0.58, 0.37, 1.0 }\nlocal TB_GRAY   = { 0.15, 0.16, 0.20, 1.0 }\nlocal TB_GRAYH  = { 0.22, 0.24, 0.29, 1.0 }\nlocal TB_LABEL  = { 0.55, 0.58, 0.63, 1.0 }\nlocal TB_TITLE  = { 0.88, 0.90, 0.93, 1.0 }\nlocal TB_DIM    = { 0.42, 0.44, 0.49, 1.0 }\nlocal TB_OK     = { 0.36, 0.80, 0.52, 1.0 }\nlocal TB_SCALE_PRESETS = { 0.8, 1.0, 1.25, 1.5 }\nRG.__ui_dirty = RG.__ui_dirty or {}\n\n-- 布局（未缩放像素）：左侧标签列 + 右侧按钮区，所有行等宽\nlocal LABEL_W, ROW_W, CELL_H, GAP = 50, 176, 22, 3\n\nlocal function _ensure_toolbox_ui()\n  _ensure_all_nodes()\n  local ui = RG.__store.data.ToolboxUI or {}\n  if type(ui.scale)  ~= \"number\"  then ui.scale  = 1.0 end\n  if type(ui.border) ~= \"number\"  then ui.border = 1 end\n  if type(ui.alpha)  ~= \"number\"  then ui.alpha  = 1.0 end\n  if type(ui.lock)   ~= \"boolean\" then ui.lock   = false end\n  if type(ui.hideRoleMit) ~= \"boolean\" then ui.hideRoleMit = false end\n  if type(ui.showTools)   ~= \"boolean\" then ui.showTools   = false end\n  if type(ui.minimized)   ~= \"boolean\" then ui.minimized   = false end\n  RG.__store.data.ToolboxUI = ui\n  return ui\nend\n\n-- on = 绿，off = 灰；static=true 时悬停不变色（锁定 / 不可用时）\nlocal function _push_seg_colors(on, static)\n  local c = on and TB_GREEN or TB_GRAY\n  local h = static and c or (on and TB_GREENH or TB_GRAYH)\n  GUI:PushStyleColor(GUI.Col_Button,        c[1],c[2],c[3],c[4])\n  GUI:PushStyleColor(GUI.Col_ButtonHovered, h[1],h[2],h[3],h[4])\n  GUI:PushStyleColor(GUI.Col_ButtonActive,  h[1],h[2],h[3],h[4])\nend\n\n-- 注：此绑定下 MenuItem 只传 label 才能正常显示，勾选状态写在文字前面\nlocal function _menu_item(label, selected)\n  return GUI:MenuItem((selected and \"> \" or \"   \") .. label)\nend\n\nlocal function _slider(ui, field, label, lo, hi, fmt)\n  local v, changed = GUI:SliderFloat(label, ui[field], lo, hi, fmt)\n  if changed then ui[field] = v; RG.__ui_dirty.ToolboxUI = true end\nend\n\nlocal function _toolbox_context_menu(ui)\n  if GUI:IsWindowHovered(GUI.HoveredFlags_ChildWindows) and GUI:IsMouseClicked(1) then\n    GUI:OpenPopup(\"tb_ctx##RG\")\n  end\n  if not GUI:BeginPopup(\"tb_ctx##RG\") then return end\n\n  if GUI:BeginMenu(\"Scale\") then\n    for _,v in ipairs(TB_SCALE_PRESETS) do\n      if _menu_item(string.format(\"%d%%\", math.floor(v*100+0.5)), math.abs(ui.scale - v) < 0.001) then\n        ui.scale = v; _save_store()\n      end\n    end\n    _slider(ui, \"scale\", \"##tb_scale\", 0.5, 2.0, \"%.2fx\")\n    GUI:EndMenu()\n  end\n  if GUI:BeginMenu(\"Border\") then\n    for _,b in ipairs({0,1,2}) do\n      if _menu_item(tostring(b), ui.border == b) then ui.border = b; _save_store() end\n    end\n    GUI:EndMenu()\n  end\n  if GUI:BeginMenu(\"Opacity\") then\n    _slider(ui, \"alpha\", \"##tb_alpha\", 0.3, 1.0, \"%.2f\")\n    GUI:EndMenu()\n  end\n  GUI:Separator()\n  if _menu_item(\"Lock\", ui.lock) then ui.lock = not ui.lock; _save_store() end\n  if _menu_item(\"Hide role mit\", ui.hideRoleMit) then ui.hideRoleMit = not ui.hideRoleMit; _save_store() end\n\n  -- 滑条拖动结束后再存一次，避免拖动中每帧写文件\n  if RG.__ui_dirty.ToolboxUI and not GUI:IsAnyItemActive() then\n    RG.__ui_dirty.ToolboxUI = false\n    _save_store()\n  end\n  GUI:EndPopup()\nend\n\nlocal tbUI   = _ensure_toolbox_ui()\nlocal S      = math.max(0.5, math.min(2.0, tbUI.scale))\nlocal locked = tbUI.lock\nlocal flags  = GUI.WindowFlags_AlwaysAutoResize + GUI.WindowFlags_NoScrollbar\n             + GUI.WindowFlags_NoTitleBar + GUI.WindowFlags_NoCollapse\nif locked then flags = flags + GUI.WindowFlags_NoMove end\n\n-- 最小化：右上角 × 收成齿轮小窗，点齿轮还原；两种状态切换时右上角对齐\nlocal GEAR_ICON = GetLuaModsPath() .. [[TensorCore\\Images\\settings.png]]\nif RG.__gearOk == nil then\n  local f = io.open(GEAR_ICON, \"rb\")\n  RG.__gearOk = (f ~= nil)\n  if f then f:close() end\nend\n\nlocal function _apply_pending_pos()\n  local p = RG.__pendingPos\n  if p then\n    GUI:SetNextWindowPos(p[1], p[2], GUI.SetCond_Always, 1, 0)\n    RG.__pendingPos = nil\n  end\nend\n\nlocal function _remember_top_right()\n  local wx, wy = GUI:GetWindowPos()\n  local ww = GUI:GetWindowSize()\n  RG.__pendingPos = { wx + ww, wy }\nend\n\nif tbUI.minimized then\n  _apply_pending_pos()\n  GUI:PushStyleVar(GUI.StyleVar_Alpha, math.max(0.3, math.min(1.0, tbUI.alpha)))\n  GUI:PushStyleVar(GUI.StyleVar_WindowBorderSize, tbUI.border)\n  GUI:PushStyleVar(GUI.StyleVar_WindowPadding, 4*S, 4*S)\n  GUI:PushStyleVar(GUI.StyleVar_WindowRounding, 8)\n  GUI:PushStyleVar(GUI.StyleVar_FrameRounding, 5)\n  GUI:Begin(\"Rikuduo's Gadget Mini###RikuduoGadgetMini\", true, flags)\n  local sz = 20*S\n  _push_seg_colors(false, false)\n  local clicked\n  if RG.__gearOk then\n    clicked = GUI:ImageButton(\"##rg_gear\", GEAR_ICON, sz, sz, 0, 0, 1, 1, 4*S, 0, 0, 0, 0, 0.85, 0.87, 0.90, 1)\n  else\n    clicked = GUI:Button(\"RG##rg_gear\", sz + 8*S, sz + 8*S)\n  end\n  GUI:PopStyleColor(3)\n  if GUI:IsItemHovered() then GUI:SetTooltip(\"Open Rikuduo's Gadget\") end\n  if clicked then\n    _remember_top_right()\n    tbUI.minimized = false\n    _save_store()\n  end\n  GUI:End()\n  GUI:PopStyleVar(5)\nelse\n_apply_pending_pos()\nGUI:PushStyleVar(GUI.StyleVar_Alpha, math.max(0.3, math.min(1.0, tbUI.alpha)))\nGUI:PushStyleVar(GUI.StyleVar_WindowBorderSize, tbUI.border)\nGUI:PushStyleVar(GUI.StyleVar_WindowPadding, 10*S, 8*S)\nGUI:PushStyleVar(GUI.StyleVar_WindowRounding, 8)\nGUI:PushStyleVar(GUI.StyleVar_FrameRounding, 5)\nGUI:PushStyleVar(GUI.StyleVar_ItemSpacing, GAP*S, GAP*S)\nGUI:Begin(\"Rikuduo's Gadget###RikuduoGadget\", true, flags)\nGUI:SetWindowFontScale(S)\n\n-- 让所有按钮恰好 CELL_H 高，文字垂直居中\nlocal padY = math.max(0, (CELL_H*S - GUI:GetTextLineHeight()) / 2)\nGUI:PushStyleVar(GUI.StyleVar_FramePadding, 6*S, padY)\n\nlocal TOTAL_W = (LABEL_W + ROW_W) * S\n\nlocal function _row_label(text)\n  GUI:AlignFirstTextHeightToWidgets()\n  GUI:TextColored(TB_LABEL[1],TB_LABEL[2],TB_LABEL[3],TB_LABEL[4], text)\n  GUI:SameLine(0, 0)\n  GUI:SetCursorPosX(GUI:GetCursorStartPos() + LABEL_W*S)\nend\n\n-- 一行等宽按钮。item: { label, on, tip, onClick, disabled }\nlocal function _chip_row(rowLabel, id, items)\n  _row_label(rowLabel)\n  local n = #items\n  local w = (ROW_W - GAP*(n-1)) / n\n  for i, it in ipairs(items) do\n    if i > 1 then GUI:SameLine(0, GAP*S) end\n    local inert = it.disabled == true\n    _push_seg_colors(it.on == true, inert)\n    if inert and not it.on then GUI:PushStyleColor(GUI.Col_Text, TB_DIM[1],TB_DIM[2],TB_DIM[3],TB_DIM[4]) end\n    local pressed = GUI:Button(it.label .. \"##\" .. id .. i, w*S, CELL_H*S)\n    if inert and not it.on then GUI:PopStyleColor() end\n    GUI:PopStyleColor(3)\n    if it.tip and GUI:IsItemHovered() then GUI:SetTooltip(it.tip) end\n    if pressed and not inert and it.onClick then it.onClick() end\n  end\nend\n\n-- 职位下拉框（完整切换面板在 [Role] Mit Control 里，这里只做紧凑的快速切换）\n-- 注：此绑定下 GUI:Combo 的索引从 1 开始；锁定时显示但不接受更改\nlocal function _combo(id, opts, current, setter, width)\n  local labels, idx = {}, 1\n  for i, o in ipairs(opts) do\n    labels[i] = o.label\n    if o.key == current then idx = i end\n  end\n  GUI:PushStyleColor(GUI.Col_FrameBg,        TB_GRAY[1],TB_GRAY[2],TB_GRAY[3],TB_GRAY[4])\n  GUI:PushStyleColor(GUI.Col_FrameBgHovered, TB_GRAYH[1],TB_GRAYH[2],TB_GRAYH[3],TB_GRAYH[4])\n  GUI:PushStyleColor(GUI.Col_FrameBgActive,  TB_GRAYH[1],TB_GRAYH[2],TB_GRAYH[3],TB_GRAYH[4])\n  _push_seg_colors(false, false) -- 下拉箭头用中性灰，不用 Minion 默认青色\n  GUI:PushItemWidth(width)\n  local newIdx = GUI:Combo(\"##\" .. id, idx, labels)\n  GUI:PopItemWidth()\n  GUI:PopStyleColor(6)\n  if locked and GUI:IsItemHovered() then GUI:SetTooltip(\"Locked - right-click to unlock\") end\n  local picked = opts[newIdx or idx]\n  if not locked and picked and picked.key ~= current then setter(picked.key) end\nend\n\n-- 单个下拉：左侧标签列 + 整行宽下拉\nlocal function _combo_row(rowLabel, id, opts, current, setter)\n  _row_label(rowLabel)\n  _combo(id, opts, current, setter, ROW_W*S)\nend\n\n-- 两个下拉并排一行：LABEL_A [▾]   LABEL_B [▾]，两个下拉等宽，整行仍等于 TOTAL_W\nlocal function _combo_pair(a, b)\n  local la = GUI:CalcTextSize(a.label)\n  local lb = GUI:CalcTextSize(b.label)\n  local inner, mid = 6*S, 10*S -- 标签与下拉之间 / 两组之间\n  local w = ((LABEL_W + ROW_W)*S - la - lb - inner*2 - mid) / 2\n  GUI:AlignFirstTextHeightToWidgets()\n  GUI:TextColored(TB_LABEL[1],TB_LABEL[2],TB_LABEL[3],TB_LABEL[4], a.label)\n  GUI:SameLine(0, inner)\n  _combo(a.id, a.opts, a.current, a.setter, w)\n  GUI:SameLine(0, mid)\n  GUI:TextColored(TB_LABEL[1],TB_LABEL[2],TB_LABEL[3],TB_LABEL[4], b.label)\n  GUI:SameLine(0, inner)\n  _combo(b.id, b.opts, b.current, b.setter, w)\nend\n\n-- ---------- Header：标题 · 环境状态 · 工具开关 ----------\ndo\n  GUI:AlignFirstTextHeightToWidgets()\n  GUI:TextColored(TB_TITLE[1],TB_TITLE[2],TB_TITLE[3],TB_TITLE[4], \"Rikuduo's Gadget\")\n\n  local optW = GUI:CalcTextSize(\"OPT\")\n  local dalW = GUI:CalcTextSize(\"DAL\")\n  local arrowW = CELL_H*S\n  local closeW = CELL_H*S\n  local gap = 8*S\n  local x0 = GUI:GetCursorStartPos()\n  GUI:SameLine(x0 + TOTAL_W - (optW + gap + dalW + gap + arrowW + GAP*S + closeW), 0)\n\n  local function _status(tag, on, name)\n    local c = on and TB_OK or TB_DIM\n    GUI:TextColored(c[1],c[2],c[3],c[4], tag)\n    if GUI:IsItemHovered() then GUI:SetTooltip(name .. (on and \": loaded\" or \": not loaded\")) end\n  end\n  _status(\"OPT\", RG.Status.optifine, \"Optifine\")\n  GUI:SameLine(0, gap)\n  _status(\"DAL\", RG.Status.dalamud, \"Dalamud\")\n  GUI:SameLine(0, gap)\n\n  _push_seg_colors(tbUI.showTools, false)\n  if GUI:ArrowButton(\"##rg_tools_toggle\", tbUI.showTools and GUI.Dir_Up or GUI.Dir_Down) then\n    tbUI.showTools = not tbUI.showTools\n    _save_store()\n  end\n  GUI:PopStyleColor(3)\n  if GUI:IsItemHovered() then GUI:SetTooltip(tbUI.showTools and \"Hide tools\" or \"Show tools\") end\n\n  -- × ：收成齿轮\n  GUI:SameLine(0, GAP*S)\n  _push_seg_colors(false, false) -- 与箭头、工具按钮同款灰底\n  if GUI:Button(\"X##rg_minimize\", closeW, CELL_H*S) then\n    _remember_top_right()\n    tbUI.minimized = true\n    _save_store()\n  end\n  GUI:PopStyleColor(3)\n  if GUI:IsItemHovered() then GUI:SetTooltip(\"Minimize to gear\") end\nend\n\n-- ---------- 职位分配（主角） ----------\nlocal job = _getJob()\nlocal isTank, isHealer, isDps = _isTankJob(job), _isHealerJob(job), _isAnyDpsJob(job)\nlocal showRoleMit = (not tbUI.hideRoleMit) and (isTank or isHealer or isDps)\n\nlocal MIT_TANK_ROLE  = { { key=\"MT\", label=\"MT\" }, { key=\"ST\", label=\"ST\" }, { key=\"Manual\", label=\"Manual\" } }\nlocal MIT_TANK_GROUP = { { key=\"MTgroup\", label=\"MT\" }, { key=\"STgroup\", label=\"ST\" }, { key=\"Manualgroup\", label=\"Manual\" } }\nlocal MIT_HEALER     = { { key=\"H1\", label=\"H1\" }, { key=\"H2\", label=\"H2\" }, { key=\"Manual\", label=\"Manual\" } }\nlocal MIT_DPS        = {\n  { key=\"D1\", label=\"D1 (Melee)\" }, { key=\"D2\", label=\"D2 (Melee)\" },\n  { key=\"D3\", label=\"D3 (Ranged)\" }, { key=\"D4\", label=\"D4 (Ranged)\" },\n  { key=\"Manual\", label=\"Manual\" },\n}\n\nif showRoleMit then\n  GUI:Separator()\n  if isTank then\n    _combo_pair(\n      { label=\"ROLE\",  id=\"tb_role\", opts=MIT_TANK_ROLE,  current=RG.GetSelectionDR(), setter=RG.SetSelectionDR },\n      { label=\"GROUP\", id=\"tb_grp\",  opts=MIT_TANK_GROUP, current=RG.GetGroupMit(),    setter=RG.SetGroupMit }\n    )\n  end\n  if isHealer then\n    _combo_row(\"HEALER\", \"tb_heal\", MIT_HEALER, RG.GetHealerRole(), RG.SetHealerRole)\n  end\n  if isDps then\n    _combo_row(\"DPS\", \"tb_dps\", MIT_DPS, RG.GetDps(), RG.SetDps)\n  end\nend\n\n-- ---------- 工具（默认收起） ----------\nif tbUI.showTools then\n  GUI:Separator()\n  local function _btn(name)\n    for _, b in ipairs(RG.Buttons) do if b[1] == name then return b[2] end end\n  end\n  local hasAC = (AnyoneCore ~= nil)\n  local devOn = hasAC and AnyoneCore.Settings and AnyoneCore.Settings.DevMonitor == true\n\n  _chip_row(\"OPEN\", \"tb_open\", {\n    { label=\"Reactions\",   tip=\"TensorReactions\",  onClick=_btn(\"Reactions\") },\n    { label=\"ACR Options\", tip=\"ACR profile options\", onClick=_btn(\"ACR Options\") },\n  })\n  _chip_row(\"DEBUG\", \"tb_dbg\", {\n    { label=\"Monitor\", on=devOn, tip=\"Dev Monitor\", onClick=_btn(\"Dev Monitor\"), disabled=not hasAC },\n    { label=\"Effects\", on=RG.Settings.showEffectTester, tip=\"Map Effects Explorer\", onClick=_btn(\"Effects Debug\") },\n    { label=\"Console\", on=RG.Settings.showConsole, tip=\"Minion console\", onClick=_btn(\"Console\") },\n  })\n\n  local dh = hasAC and AnyoneCore.Settings and AnyoneCore.Settings.DutyHelper\n  _chip_row(\"AUTO\", \"tb_auto\", {\n    { label=\"Combat\", on=(gStartCombat == true), tip=\"Start combat (gStartCombat)\",\n      onClick=function() gStartCombat = not gStartCombat end },\n    { label=\"DutyHelper\", on=(dh and dh.enabled == true), disabled=(dh == nil), tip=\"AnyoneCore DutyHelper\",\n      onClick=function() dh.enabled = not dh.enabled end },\n  })\n\n  local sw = RG.__store.data.SwitchUI\n  _chip_row(\"SWITCH\", \"tb_sw\", {\n    { label=\"Show\", on=(sw.showSwitch == true), tip=\"Show the Role / Group switch bar\",\n      onClick=function() sw.showSwitch = not sw.showSwitch; _save_store() end },\n    { label=\"Instance only\", on=(sw.showSwitch == true and sw.onlyInInstance == true),\n      disabled=(sw.showSwitch ~= true), tip=\"Only show the switch bar inside instances\",\n      onClick=function() sw.onlyInInstance = not sw.onlyInInstance; _save_store() end },\n  })\nend\n\n-- 保证窗口宽度固定（只有标题行时也一样宽）\nGUI:Dummy(TOTAL_W, 0)\n\n_toolbox_context_menu(tbUI)\nGUI:PopStyleVar() -- FramePadding\nGUI:End()\nGUI:PopStyleVar(6)\nend -- if tbUI.minimized\n\n-- Minion Console（点 X 关闭时 ShowConsole 返回 false，同步关掉开关）\nif RG.Settings.showConsole then\n  RG.Settings.showConsole = (GUI:ShowConsole(true) ~= false)\nend\n\n-- ============================================================\n-- MAP EFFECTS DEBUGGER (DUAL PANE) — LJ 原版完整机能恢复\n-- ============================================================\nif RG.Settings.showEffectTester then\n  GUI:SetNextWindowSize(1100, 600, GUI.SetCond_FirstUseEver)\n  local visible, open = GUI:Begin(\"Map Effects Explorer###RG_EffectDebugger\", RG.Settings.showEffectTester)\n  if not open then RG.Settings.showEffectTester = false end\n\n  if visible then\n    local typeNames = { [2] = \"Model\", [4] = \"VFX\", [6] = \"Script\", [7] = \"Sound\" }\n\n    if GUI:Button(\"Refresh List\", 100, 24) then RG.RefreshMapEffects() end\n    GUI:SameLine()\n\n    RG.Settings.searchFilter = RG.Settings.searchFilter or \"\"\n    local filterLower = string.lower(RG.Settings.searchFilter)\n\n    local filteredItems = {}\n    for _, item in ipairs(RG.State.mapEffectsCache) do\n      if filterLower == \"\" or string.find(item.searchString, filterLower, 1, true) then\n        table.insert(filteredItems, item)\n      end\n    end\n\n    GUI:PushItemWidth(300)\n    RG.Settings.searchFilter = GUI:InputText(\"Search Filter\", RG.Settings.searchFilter)\n    GUI:PopItemWidth()\n    GUI:Spacing()\n\n    GUI:Columns(2, \"MapEffectsColumns\", true)\n\n    -- LEFT PANE\n    GUI:BeginChild(\"ME_LeftList\", 0, 0, true)\n    for _, item in ipairs(filteredItems) do\n      local isSelected = (RG.Settings.selectedIndex == item.index)\n\n      if isSelected then\n        GUI:PushStyleColor(GUI.Col_Text, 1.0, 0.2, 0.2, 1.0) -- Selected Red\n      elseif item.isActive then\n        GUI:PushStyleColor(GUI.Col_Text, 0.9, 0.9, 0.9, 1.0) -- Active White\n      else\n        GUI:PushStyleColor(GUI.Col_Text, 0.5, 0.5, 0.5, 1.0) -- Inactive Grey\n      end\n\n      if GUI:Selectable(item.label, isSelected) then\n        RG.Settings.selectedIndex = item.index\n      end\n      GUI:PopStyleColor()\n    end\n    GUI:EndChild()\n\n    GUI:NextColumn()\n\n    -- RIGHT PANE (FULL)\n    GUI:BeginChild(\"ME_RightTree\", 0, 0, true)\n    if RG.Settings.selectedIndex ~= -1 then\n      local targetRes = nil\n      if Argus and Argus.getMapEffectResource then\n        targetRes = Argus.getMapEffectResource(RG.Settings.selectedIndex)\n      end\n\n      if targetRes then\n        local id, path, rType, isActive = Argus.getEffectResourceInfo(targetRes)\n        local rTypeStr = typeNames[rType] or tostring(rType)\n\n        -- Top Header\n        GUI:TextColored(0.95, 0.75, 0.20, 1.0, string.format(\"Index: %d\", RG.Settings.selectedIndex))\n        GUI:SameLine(100)\n        GUI:TextColored(0.40, 0.75, 1.00, 1.0, string.format(\"ID: %d\", id or 0))\n        GUI:SameLine(200)\n        GUI:TextColored(0.95, 0.75, 0.20, 1.0, string.format(\"Type: %s (%d)\", rTypeStr, rType or 0))\n        GUI:SameLine(350)\n\n        if isActive then\n          GUI:TextColored(0.30, 0.90, 0.40, 1.0, \"Status: ACTIVE\")\n        else\n          GUI:TextColored(0.60, 0.60, 0.60, 1.0, \"Status: INACTIVE\")\n        end\n\n        GUI:Spacing()\n        GUI:TextColored(0.8, 0.8, 0.8, 1.0, \"Path: \")\n        GUI:SameLine()\n        GUI:TextColored(1.0, 1.0, 1.0, 1.0, tostring(path))\n\n        GUI:SameLine()\n        if GUI:Button(\"[Copy]##Path\", 45, 18) then\n          if GUI and GUI.SetClipboardText then GUI:SetClipboardText(tostring(path)) end\n        end\n\n        GUI:Separator()\n        GUI:Spacing()\n\n        -- Actions\n        GUI:Text(\"Actions:\")\n        GUI:SameLine()\n        if GUI:Button(\"Teleport to Me\", 120, 20) then\n          if TensorCore and TensorCore.mGetPlayer then\n            local p = TensorCore.mGetPlayer()\n            if p and p.pos then\n              Argus.setEffectResourcePosition(targetRes, p.pos.x, p.pos.y, p.pos.z)\n            end\n          end\n        end\n        GUI:SameLine()\n        if GUI:Button(\"Turn Off (Flag 4)\", 120, 20) then\n          Argus.runMapEffect(RG.Settings.selectedIndex, 0, 4)\n        end\n\n        GUI:Spacing()\n        GUI:Separator()\n        GUI:Spacing()\n\n        -- Properties\n        local px, py, pz = Argus.getEffectResourcePosition(targetRes)\n        if px then\n          GUI:TextColored(0.4, 0.8, 1.0, 1.0, string.format(\"Position: X: %.3f   Y: %.3f   Z: %.3f\", px, py, pz))\n        end\n\n        local sx, sy, sz = Argus.getEffectResourceScale(targetRes)\n        if sx then\n          GUI:TextColored(0.4, 1.0, 0.4, 1.0, string.format(\"Scale: X: %.3f   Y: %.3f   Z: %.3f\", sx, sy, sz))\n        end\n\n        local dx, dy, dz, ux, uy, uz = Argus.getEffectResourceOrientation(targetRes)\n        if dx then\n          GUI:TextColored(1.0, 0.6, 0.6, 1.0,\n            string.format(\"Dir: X: %.3f  Y: %.3f  Z: %.3f   |   Up: X: %.3f  Y: %.3f  Z: %.3f\", dx, dy, dz, ux, uy, uz))\n        end\n\n        local rt, rs = Argus.getEffectResourceRenderInfo(targetRes)\n        if rt then\n          GUI:Spacing()\n          GUI:TextColored(0.8, 0.8, 0.8, 1.0, string.format(\"Render Type: %s   |   Render State: %s\", tostring(rt), tostring(rs)))\n        end\n\n        GUI:Spacing()\n        GUI:Separator()\n        GUI:Spacing()\n\n        -- Flat Hierarchy Viewer for Type 6\n        if rType == 6 then\n          local rawNumScripts = Argus.getNumEffectResourceScripts(targetRes) or 0\n\n          local validScripts = {}\n          for si = 0, rawNumScripts - 1 do\n            local sName, sNumSub, sRes, sRunning = Argus.getEffectResourceScriptInfo(targetRes, si)\n            if sName and sName ~= \"\" then\n              table.insert(validScripts, { index=si, name=sName, numSub=sNumSub, res=sRes, running=sRunning })\n            end\n          end\n\n          if #validScripts > 0 then\n            GUI:TextColored(0.95, 0.75, 0.20, 1.0, \"--- Script Explorer (\" .. #validScripts .. \" loaded) ---\")\n            GUI:Spacing()\n\n            for _, sInfo in ipairs(validScripts) do\n              local scriptFlag = math.floor(2 ^ sInfo.index)\n              local statusColor = sInfo.running and {0.3, 0.9, 0.4} or {0.9, 0.3, 0.3}\n\n              GUI:TextColored(statusColor[1], statusColor[2], statusColor[3], 1.0,\n                string.format(\"[%d] %s (Flag: %d)\", sInfo.index, tostring(sInfo.name), scriptFlag))\n\n              GUI:SameLine(350)\n              if GUI:Button(\"Run##\" .. sInfo.index, 40, 18) then\n                Argus.startEffectResourceScript(targetRes, sInfo.index, 0)\n              end\n              GUI:SameLine()\n              if GUI:Button(\"Stop##\" .. sInfo.index, 40, 18) then\n                Argus.runMapEffect(RG.Settings.selectedIndex, 0, 4)\n              end\n              GUI:SameLine()\n              if GUI:Button(\"Copy Reaction##\" .. sInfo.index, 110, 18) then\n                local reactionStr = string.format(\n                  \"return eventArgs.a1 == %d and eventArgs.a2 == 0 and eventArgs.a3 == %d\",\n                  RG.Settings.selectedIndex, scriptFlag\n                )\n                if GUI and GUI.SetClipboardText then\n                  GUI:SetClipboardText(reactionStr)\n                end\n              end\n\n              -- Inner Subresources\n              if sInfo.res and sInfo.numSub and sInfo.numSub > 0 then\n                for subI = 0, sInfo.numSub - 1 do\n                  local ssRes = Argus.getEffectResourceScriptSubresource(sInfo.res, subI)\n                  if ssRes then\n                    local ssId, ssPath, ssType, ssActive = Argus.getEffectResourceInfo(ssRes)\n                    local ssTypeStr = typeNames[ssType] or tostring(ssType)\n                    local shortPath = type(ssPath) == \"string\" and (ssPath:match(\".*/(.*)\") or ssPath) or \"Unknown\"\n\n                    GUI:TextColored(0.5, 0.5, 0.5, 1.0, \"      ↳ \")\n                    GUI:SameLine()\n                    GUI:TextColored(0.7, 0.7, 0.7, 1.0,\n                      string.format(\"[%s] ID: %d | %s\", ssTypeStr, ssId or 0, shortPath))\n                    if GUI:IsItemHovered() then GUI:SetTooltip(tostring(ssPath)) end\n                  end\n                end\n              end\n\n              GUI:Spacing()\n            end\n          end\n\n          -- Full Outer Subresources List\n          local numFullSub = Argus.getNumEffectSubresources(targetRes) or 0\n          if numFullSub > 0 then\n            GUI:Spacing()\n            GUI:TextColored(0.40, 0.75, 1.00, 1.0, \"--- Full Resource Pool (\" .. numFullSub .. \" total) ---\")\n            GUI:Spacing()\n\n            for fi = 0, numFullSub - 1 do\n              local fRes = Argus.getEffectSubresource(targetRes, fi)\n              if fRes then\n                local fId, fPath, fType, fActive = Argus.getEffectResourceInfo(fRes)\n                local fTypeStr = typeNames[fType] or tostring(fType)\n                local aColor = fActive and {0.9, 0.9, 0.9} or {0.5, 0.5, 0.5}\n\n                GUI:TextColored(aColor[1], aColor[2], aColor[3], 1.0,\n                  string.format(\"[%d] %s | ID: %d\", fi, fTypeStr, fId or 0))\n                GUI:SameLine(180)\n                GUI:TextColored(0.6, 0.6, 0.6, 1.0, tostring(fPath))\n              end\n            end\n          end\n        end\n      else\n        GUI:TextColored(1.0, 0.4, 0.4, 1.0, \"Resource is nil or despawned.\")\n      end\n    else\n      GUI:TextColored(0.5, 0.5, 0.5, 1.0, \"Select a map effect from the list on the left to inspect.\")\n    end\n    GUI:EndChild()\n\n    GUI:Columns(1)\n  end\n\n  GUI:End()\nend\n\nself.used = true",
