					{
						aType = "Lua",
						actionLua = "-- ===== Role Panel — Tank / Healer / DPS 统一面板（按当前职业自动切换）=====\n-- 整合原 [Tank] Mit Control、[Healer] Healer Panel、[DPS] UI Control。\n-- 风格：Classic（大方块）/ Modern（分段按钮）/ Compact（团本小横条），每个职业各自一份设置。\n-- 窗口：标题统一为 \"Role Panel\"，内部 ID 按职业区分（###RG_Tank / ###RG_Healer / ###RG_Dps），各自记住位置。\n-- 右键窗口任意位置：切换风格、缩放、边框、透明度、锁定、直接修改选择。\n-- 存档：沿用 SelectionDR.lua 中的 SelectionDR / GroupMit / HealerRole / DpsPanel 与 TankMitUI / HealerUI / DpsUI 节点。\n\n-- 便携路径\nlocal LUA_MODS  = GetLuaModsPath()\nlocal SAVE_DIR  = LUA_MODS .. [[TensorReactions\\GeneralReactions\\Rikuduo_s_Gadgets\\Settings]]\nlocal SAVE_FILE = SAVE_DIR .. [[\\SelectionDR.lua]]\n\n-- 目录确保\nlocal function ensure_dir_tree(path)\n    if not FolderExists(path) then\n        local acc = \"\"\n        for part in string.gmatch(path, [[[^\\\\]+]]) do\n            acc = (acc == \"\") and part or (acc .. [[\\]] .. part)\n            if not FolderExists(acc) then FolderCreate(acc) end\n        end\n    end\nend\n\n-- 共享存储（多个 Reaction 共用）\n_G.RikuduoGadget = _G.RikuduoGadget or {}\nlocal RG = _G.RikuduoGadget\nRG.__store = RG.__store or { loaded=false, data=nil }\n\nlocal function load_store()\n    if RG.__store.loaded then return end\n    local ok, data = pcall(FileLoad, SAVE_FILE)\n    if ok and type(data)==\"table\" then\n        -- 兼容旧版：如果顶层就是 state/order，则迁移到 SelectionDR 节点\n        if data.state and data.order and (not data.SelectionDR) then\n            data = { SelectionDR = { state=data.state, order=data.order } }\n        end\n        RG.__store.data = data\n    else\n        RG.__store.data = {}\n    end\n    RG.__store.loaded = true\nend\n\nlocal function save_store()\n    ensure_dir_tree(SAVE_DIR)\n    FileSave(SAVE_FILE, RG.__store.data)\nend\n\n-- ===== 选择节点（单选：keys[1] 默认选中）=====\nlocal NODE_KEYS = {\n    SelectionDR = { \"MT\", \"ST\", \"Manual\" },\n    GroupMit    = { \"MTgroup\", \"STgroup\", \"Manualgroup\" },\n    HealerRole  = { \"H1\", \"H2\", \"Manual\" },\n    DpsPanel    = { \"D1\", \"D2\", \"D3\", \"D4\", \"Manual\" },\n}\n\nlocal function ensure_node(nodeName)\n    load_store()\n    local keys = NODE_KEYS[nodeName]\n    local node = RG.__store.data[nodeName] or {}\n    node.order = node.order or {}\n    node.state = node.state or {}\n    for _,k in ipairs(keys) do\n        if type(node.state[k]) ~= \"boolean\" then node.state[k] = (k==keys[1]) end\n        local found=false; for __,v in ipairs(node.order) do if v==k then found=true end end\n        if not found then table.insert(node.order, k) end\n    end\n    RG.__store.data[nodeName] = node\n    return node\nend\n\nlocal function get_selected(nodeName)\n    local node = ensure_node(nodeName)\n    for _,name in ipairs(node.order) do\n        if node.state[name] then return name end\n    end\n    return NODE_KEYS[nodeName][1]\nend\n\nlocal function select_only(node, key)\n    for k,_ in pairs(node.state) do node.state[k] = (k==key) end\n    save_store()\nend\n\nlocal function set_selected(nodeName, key)\n    local node = ensure_node(nodeName)\n    if node.state[key] == nil then return false end\n    select_only(node, key)\n    return true\nend\n\n-- ===== 对外接口（Condition / Timeline 使用；不论当前职业都会定义）=====\nfunction RG.selection()        return get_selected(\"SelectionDR\") end   -- \"MT\"/\"ST\"/\"Manual\"\nfunction RG.is(name)           return get_selected(\"SelectionDR\") == name end\nfunction RG.group_selection()  return get_selected(\"GroupMit\") end      -- \"MTgroup\"/\"STgroup\"/\"Manualgroup\"\nfunction RG.group_is(name)     return get_selected(\"GroupMit\") == name end\nfunction RG.healer_selection() return get_selected(\"HealerRole\") end    -- \"H1\"/\"H2\"/\"Manual\"\nfunction RG.healer_is(name)    return get_selected(\"HealerRole\") == name end\nRG.GetDps = function() return get_selected(\"DpsPanel\") end              -- \"D1\"..\"D4\"/\"Manual\"\nRG.SetDps = function(name) return set_selected(\"DpsPanel\", name) end\nRG.dps_is = function(name) return get_selected(\"DpsPanel\") == name end\n-- 与 Rikuduo's Gadget 共用的 Get/Set 接口\nRG.GetSelectionDR = function() return get_selected(\"SelectionDR\") end\nRG.SetSelectionDR = function(name) return set_selected(\"SelectionDR\", name) end\nRG.GetGroupMit    = function() return get_selected(\"GroupMit\") end\nRG.SetGroupMit    = function(name) return set_selected(\"GroupMit\", name) end\nRG.GetHealerRole  = function() return get_selected(\"HealerRole\") end\nRG.SetHealerRole  = function(name) return set_selected(\"HealerRole\", name) end\n\n-- ===== show switch 联动：关了就不画 UI =====\nlocal function show_switch_enabled()\n    -- 1) 优先用 Toolbox API\n    if RG.ShowSwitchEnabled then\n        return RG.ShowSwitchEnabled() == true\n    end\n    if RG.show_switch then\n        return RG.show_switch() == true\n    end\n\n    -- 2) 兜底：从存档读 SwitchUI\n    load_store()\n    local sw = RG.__store.data and RG.__store.data.SwitchUI\n    if not sw or type(sw.showSwitch) ~= \"boolean\" then\n        return true -- 默认显示\n    end\n    if sw.showSwitch ~= true then\n        return false\n    end\n\n    -- 3) only in instance\n    if sw.onlyInInstance == true then\n        if type(InInstance) == \"function\" then\n            return InInstance() == true\n        end\n        return false\n    end\n\n    return true\nend\n\nif not show_switch_enabled() then\n    self.used = true\n    return\nend\n\n-- ===== 职业判断 =====\nlocal TANK_JOBS   = { [19]=true, [21]=true, [32]=true, [37]=true }                     -- PLD/WAR/DRK/GNB\nlocal HEALER_JOBS = { [24]=true, [28]=true, [33]=true, [40]=true }                     -- WHM/SCH/AST/SGE\nlocal DPS_JOBS    = { [34]=true, [20]=true, [30]=true, [22]=true, [39]=true, [41]=true, -- SAM/MNK/NIN/DRG/RPR/VPR\n                      [23]=true, [31]=true, [38]=true, [27]=true, [25]=true, [42]=true } -- BRD/MCH/DNC/SMN/BLM/PCT\n\nlocal function current_role()\n    if not TensorCore or not TensorCore.mGetPlayer then return nil end\n    local p = TensorCore.mGetPlayer()\n    local job = p and p.job or 0\n    if TANK_JOBS[job] then return \"tank\" end\n    if HEALER_JOBS[job] then return \"healer\" end\n    if DPS_JOBS[job] then return \"dps\" end\n    return nil\nend\n\nlocal ROLE = current_role()\nif not ROLE then\n    self.used = true\n    return\nend\n\n-- ===== 各职业面板配置 =====\nlocal GROUP_LABELS = { MTgroup=\"MT\", STgroup=\"ST\", Manualgroup=\"Manual\" }\n\nlocal function cp(fn, arg) return \"return (RikuduoGadget and RikuduoGadget.\" .. fn .. \" and \" .. arg .. \") or false\" end\n\nlocal ROLES = {\n    tank = {\n        id = \"RG_Tank\", uiNode = \"TankMitUI\", prefix = \"tank\",\n        groups = {\n            { title=\"Role mit\",  col=\"RoleMit\",  short=\"Role\",  node=\"SelectionDR\" },\n            { title=\"Group mit\", col=\"GroupMit\", short=\"Group\", node=\"GroupMit\", labels=GROUP_LABELS },\n        },\n        -- 快捷复制：每列对应一组\n        copy = {\n            {\n                { \"MT\",       cp(\"is\", 'RikuduoGadget.is(\"MT\")') },\n                { \"ST\",       cp(\"is\", 'RikuduoGadget.is(\"ST\")') },\n                { \"Manual\",   cp(\"is\", 'RikuduoGadget.is(\"Manual\")') },\n                { \"MT or ST\", cp(\"is\", '(RikuduoGadget.is(\"MT\") or RikuduoGadget.is(\"ST\"))') },\n            },\n            {\n                { \"MT\",       cp(\"group_is\", 'RikuduoGadget.group_is(\"MTgroup\")') },\n                { \"ST\",       cp(\"group_is\", 'RikuduoGadget.group_is(\"STgroup\")') },\n                { \"Manual\",   cp(\"group_is\", 'RikuduoGadget.group_is(\"Manualgroup\")') },\n                { \"MT or ST\", cp(\"group_is\", '(RikuduoGadget.group_is(\"MTgroup\") or RikuduoGadget.group_is(\"STgroup\"))') },\n            },\n        },\n    },\n    healer = {\n        id = \"RG_Healer\", uiNode = \"HealerUI\", prefix = \"heal\",\n        groups = {\n            { title=\"Healer\", short=\"Healer\", node=\"HealerRole\" },\n        },\n        copy = {\n            {\n                { \"H1\",       cp(\"healer_is\", 'RikuduoGadget.healer_is(\"H1\")') },\n                { \"H2\",       cp(\"healer_is\", 'RikuduoGadget.healer_is(\"H2\")') },\n                { \"Manual\",   cp(\"healer_is\", 'RikuduoGadget.healer_is(\"Manual\")') },\n                { \"H1 or H2\", cp(\"healer_is\", '(RikuduoGadget.healer_is(\"H1\") or RikuduoGadget.healer_is(\"H2\"))') },\n            },\n        },\n    },\n    dps = {\n        id = \"RG_Dps\", uiNode = \"DpsUI\", prefix = \"dps\",\n        groups = {\n            {\n                title=\"DPS\", short=\"DPS\", node=\"DpsPanel\",\n                -- Modern：D1-D4 一行；Melee/Range 指示（不可点）+ Manual 一行\n                row1 = { \"D1\", \"D2\", \"D3\", \"D4\" },\n                manual = \"Manual\",\n                indicators = {\n                    { \"Melee\", { D1=true, D2=true } },\n                    { \"Range\", { D3=true, D4=true } },\n                },\n            },\n        },\n        copy = {\n            {\n                { \"D1\",     cp(\"dps_is\", 'RikuduoGadget.dps_is(\"D1\")') },\n                { \"D2\",     cp(\"dps_is\", 'RikuduoGadget.dps_is(\"D2\")') },\n                { \"D3\",     cp(\"dps_is\", 'RikuduoGadget.dps_is(\"D3\")') },\n                { \"D4\",     cp(\"dps_is\", 'RikuduoGadget.dps_is(\"D4\")') },\n                { \"Manual\", cp(\"dps_is\", 'RikuduoGadget.dps_is(\"Manual\")') },\n                { \"Melee\",  cp(\"dps_is\", '(RikuduoGadget.dps_is(\"D1\") or RikuduoGadget.dps_is(\"D2\"))') },\n                { \"Range\",  cp(\"dps_is\", '(RikuduoGadget.dps_is(\"D3\") or RikuduoGadget.dps_is(\"D4\"))') },\n            },\n        },\n    },\n}\nlocal CFG = ROLES[ROLE]\n\n-- ===== UI 设置（每个职业、每种风格各自一份缩放/边框/透明度）=====\nlocal STYLES = { \"Classic\", \"Modern\", \"Compact\" }\nlocal SCALE_PRESETS = { 0.8, 1.0, 1.25, 1.5 }\n\nlocal function ensure_ui()\n    load_store()\n    local ui = RG.__store.data[CFG.uiNode] or {}\n    if ui.style ~= \"Classic\" and ui.style ~= \"Modern\" and ui.style ~= \"Compact\" then ui.style = \"Classic\" end\n    if type(ui.lock) ~= \"boolean\" then ui.lock = false end\n    ui.per = ui.per or {}\n    for _,s in ipairs(STYLES) do\n        local p = ui.per[s] or {}\n        if type(p.scale)  ~= \"number\" then p.scale  = 1.0 end\n        if type(p.border) ~= \"number\" then p.border = 1 end\n        if type(p.alpha)  ~= \"number\" then p.alpha  = 1.0 end\n        ui.per[s] = p\n    end\n    RG.__store.data[CFG.uiNode] = ui\n    return ui\nend\n\n-- UI 常量（未缩放）——与 Rikuduo's Gadget 共用同一套尺寸与配色\n-- 左侧灰色大写标签列 + 右侧按钮区；绿 = 已选，灰 = 未选；按钮高 22，圆角 5，窗口圆角 8，无标题栏\nlocal LABEL_W, ROW_W, CELL_H, GAP = 50, 176, 22, 3\nlocal BIG_H = 32           -- Classic 大按钮高度\nlocal COMPACT_W = 56\nlocal GREEN  = { 0.18, 0.49, 0.31, 1.0 }\nlocal GREENH = { 0.22, 0.58, 0.37, 1.0 }\nlocal GRAY   = { 0.15, 0.16, 0.20, 1.0 }\nlocal GRAYH  = { 0.22, 0.24, 0.29, 1.0 }\nlocal LABEL  = { 0.55, 0.58, 0.63, 1.0 }\nlocal TITLE  = { 0.88, 0.90, 0.93, 1.0 }\nlocal DIM    = { 0.42, 0.44, 0.49, 1.0 }\nlocal COPIED_MS = 1500\nlocal ROLE_TITLE = { tank=\"Tank Mit\", healer=\"Healer Mit\", dps=\"DPS Mit\" }\nRG.__copied = RG.__copied or { id=nil, t=0 }\nRG.__ui_dirty = RG.__ui_dirty or {}\n\nlocal function label_of(g, key) return (g.labels and g.labels[key]) or key end\n\nlocal function current_label(g, node)\n    for _,k in ipairs(node.order) do\n        if node.state[k] then return label_of(g, k) end\n    end\n    return \"-\"\nend\n\nlocal function cycle(node)\n    local n = #node.order\n    if n == 0 then return end\n    local cur = 0\n    for i,k in ipairs(node.order) do if node.state[k] then cur = i end end\n    select_only(node, node.order[(cur % n) + 1])\nend\n\nlocal function push_button_colors(on, static)\n    local c = on and GREEN or GRAY\n    local h = static and c or (on and GREENH or GRAYH)\n    GUI:PushStyleColor(GUI.Col_Button,        c[1],c[2],c[3],c[4])\n    GUI:PushStyleColor(GUI.Col_ButtonHovered, h[1],h[2],h[3],h[4])\n    GUI:PushStyleColor(GUI.Col_ButtonActive,  h[1],h[2],h[3],h[4])\nend\n\nlocal function text_label(text)\n    GUI:TextColored(LABEL[1],LABEL[2],LABEL[3],LABEL[4], text)\nend\n\n-- 左侧标签列（空字符串 = 续行，只占位）\nlocal function row_label(text, S)\n    GUI:AlignFirstTextHeightToWidgets()\n    text_label(text ~= \"\" and text or \" \")\n    GUI:SameLine(0, 0)\n    GUI:SetCursorPosX(GUI:GetCursorStartPos() + LABEL_W*S)\nend\n\n-- 一个按钮。static = 不可点（指示灯 / 锁定）\nlocal function chip(label, id, w, h, on, static, tip)\n    push_button_colors(on, static)\n    if static and not on then GUI:PushStyleColor(GUI.Col_Text, DIM[1],DIM[2],DIM[3],DIM[4]) end\n    local pressed = GUI:Button(label .. \"##\" .. id, w, h)\n    if static and not on then GUI:PopStyleColor() end\n    GUI:PopStyleColor(3)\n    if tip and GUI:IsItemHovered() then GUI:SetTooltip(tip) end\n    return pressed and not static\nend\n\nlocal LOCK_TIP = \"Locked - right-click to unlock\"\n\n-- ----- Classic：大按钮，每组一列，列宽平分整行 -----\nlocal function draw_classic(nodes, S, locked)\n    local n = #CFG.groups\n    local colW = ((LABEL_W + ROW_W) - GAP*(n-1)) / n\n    local x0 = GUI:GetCursorStartPos()\n    -- 列标题\n    for gi,g in ipairs(CFG.groups) do\n        if gi > 1 then GUI:SameLine(x0 + (gi-1)*(colW + GAP)*S, 0) end\n        text_label(string.upper(g.short))\n    end\n    local rows = 0\n    for gi,_ in ipairs(CFG.groups) do rows = math.max(rows, #nodes[gi].order) end\n    for i=1,rows do\n        for gi,g in ipairs(CFG.groups) do\n            if gi > 1 then GUI:SameLine(x0 + (gi-1)*(colW + GAP)*S, 0) end\n            local node = nodes[gi]\n            local key = node.order[i]\n            if key then\n                local on = node.state[key] == true\n                if chip(label_of(g, key), CFG.prefix..\"_cl_\"..g.node..\"_\"..key, colW*S, BIG_H*S,\n                        on, locked and not on, locked and LOCK_TIP or nil) then\n                    select_only(node, key)\n                end\n            else\n                GUI:Dummy(colW*S, BIG_H*S)\n            end\n        end\n    end\nend\n\n-- ----- Modern：每组一行分段按钮（与 Toolbox 行布局一致）-----\nlocal function seg_row(rowLabel, g, node, keys, S, locked, extra)\n    row_label(rowLabel, S)\n    local n = #keys + (extra and #extra or 0)\n    local w = (ROW_W - GAP*(n-1)) / n\n    local idx = 0\n    if extra then\n        -- extra：状态指示（不可点），放在前面\n        for _,ind in ipairs(extra) do\n            idx = idx + 1\n            if idx > 1 then GUI:SameLine(0, GAP*S) end\n            chip(ind.label, CFG.prefix..\"_ind_\"..idx, w*S, CELL_H*S, ind.on, true, ind.tip)\n        end\n    end\n    for _,key in ipairs(keys) do\n        idx = idx + 1\n        if idx > 1 then GUI:SameLine(0, GAP*S) end\n        local on = node.state[key] == true\n        if chip(label_of(g, key), CFG.prefix..\"_m_\"..g.node..\"_\"..key, w*S, CELL_H*S,\n                on, locked and not on, locked and LOCK_TIP or nil) then\n            select_only(node, key)\n        end\n    end\nend\n\nlocal function draw_modern(nodes, S, locked)\n    for gi,g in ipairs(CFG.groups) do\n        local node = nodes[gi]\n        if g.indicators then\n            seg_row(string.upper(g.short), g, node, g.row1, S, locked)\n            local cur = get_selected(g.node)\n            local extra = {}\n            for _,ind in ipairs(g.indicators) do\n                extra[#extra+1] = { label=ind[1], on=(ind[2][cur] == true), tip=\"Follows D1-D4\" }\n            end\n            seg_row(\"\", g, node, { g.manual }, S, locked, extra)\n        else\n            seg_row(string.upper(g.short), g, node, node.order, S, locked)\n        end\n    end\nend\n\n-- ----- Compact：团本小横条（ROLE [当前]  GROUP [当前]，点击轮换；锁定时金色边框）-----\nlocal function draw_compact(nodes, S, locked)\n    for gi,g in ipairs(CFG.groups) do\n        local node = nodes[gi]\n        if gi > 1 then GUI:SameLine(0, 12*S) end\n        GUI:AlignFirstTextHeightToWidgets()\n        text_label(string.upper(g.short))\n        GUI:SameLine(0, 6*S)\n        push_button_colors(true, locked)\n        if GUI:Button(current_label(g, node) .. \"##\" .. CFG.prefix .. \"_c_\" .. g.node, COMPACT_W*S, CELL_H*S) and not locked then\n            cycle(node)\n        end\n        GUI:PopStyleColor(3)\n        if GUI:IsItemHovered() then GUI:SetTooltip(locked and LOCK_TIP or \"Click to cycle\") end\n    end\nend\n\n-- ----- 复制条件 Lua（Classic / Modern，标题行箭头展开）：每组一行起，3 列网格 -----\nlocal function copy_chip(id, entry, w, S)\n    local c = RG.__copied\n    local done = (c.id == id and TimeSince(c.t) < COPIED_MS)\n    if chip(done and \"Copied!\" or entry[1], id, w, CELL_H*S, done, false, \"Copy condition Lua\") then\n        GUI:SetClipboardText(entry[2])\n        c.id, c.t = id, Now()\n    end\nend\n\nlocal function draw_copy_section(S)\n    local COLS = 3\n    local w = (ROW_W - GAP*(COLS-1)) / COLS\n    text_label(\"Copy condition Lua\")\n    for ci,col in ipairs(CFG.copy) do\n        local g = CFG.groups[ci] or CFG.groups[1]\n        for i,entry in ipairs(col) do\n            local c = (i - 1) % COLS\n            if c == 0 then\n                row_label(i == 1 and string.upper(g.short) or \"\", S)\n            else\n                GUI:SameLine(0, GAP*S)\n            end\n            copy_chip(CFG.prefix .. \"_cp_\" .. ci .. \"_\" .. i, entry, w*S, S)\n        end\n    end\nend\n\n-- 标题行：标题 + 右侧箭头（展开复制区）\nlocal function draw_header(ui, S)\n    GUI:AlignFirstTextHeightToWidgets()\n    GUI:TextColored(TITLE[1],TITLE[2],TITLE[3],TITLE[4], ROLE_TITLE[ROLE] or \"Role Panel\")\n    local x0 = GUI:GetCursorStartPos()\n    GUI:SameLine(x0 + (LABEL_W + ROW_W)*S - CELL_H*S, 0)\n    push_button_colors(ui.showCopy, false)\n    if GUI:ArrowButton(\"##\" .. CFG.prefix .. \"_copy_toggle\", ui.showCopy and GUI.Dir_Up or GUI.Dir_Down) then\n        ui.showCopy = not ui.showCopy\n        save_store()\n    end\n    GUI:PopStyleColor(3)\n    if GUI:IsItemHovered() then GUI:SetTooltip(ui.showCopy and \"Hide condition copy\" or \"Copy condition Lua\") end\nend\n\n-- ----- 右键菜单 -----\n-- 注：此绑定下 MenuItem 只传 label 才能正常显示，勾选状态写在文字前面\nlocal function menu_item(label, selected)\n    return GUI:MenuItem((selected and \"> \" or \"   \") .. label)\nend\n\nlocal function slider(p, field, label, lo, hi, fmt)\n    local v, changed = GUI:SliderFloat(label, p[field], lo, hi, fmt)\n    if changed then p[field] = v; RG.__ui_dirty[CFG.uiNode] = true end\nend\n\nlocal function draw_context_menu(ui, nodes)\n    local popup = CFG.prefix .. \"_ctx\"\n    if GUI:IsWindowHovered(GUI.HoveredFlags_ChildWindows) and GUI:IsMouseClicked(1) then\n        GUI:OpenPopup(popup)\n    end\n    if not GUI:BeginPopup(popup) then return end\n    local p = ui.per[ui.style]\n\n    GUI:TextDisabled(\"Style\")\n    for _,s in ipairs(STYLES) do\n        if menu_item(s, ui.style == s) and ui.style ~= s then\n            ui.style = s; save_store()\n        end\n    end\n    GUI:Separator()\n\n    if GUI:BeginMenu(\"Scale\") then\n        for _,v in ipairs(SCALE_PRESETS) do\n            if menu_item(string.format(\"%d%%\", math.floor(v*100+0.5)), math.abs(p.scale - v) < 0.001) then\n                p.scale = v; save_store()\n            end\n        end\n        slider(p, \"scale\", \"##\" .. CFG.prefix .. \"_scale\", 0.5, 2.0, \"%.2fx\")\n        GUI:EndMenu()\n    end\n    if GUI:BeginMenu(\"Border\") then\n        for _,b in ipairs({0,1,2}) do\n            if menu_item(tostring(b), p.border == b) then p.border = b; save_store() end\n        end\n        GUI:EndMenu()\n    end\n    if GUI:BeginMenu(\"Opacity\") then\n        slider(p, \"alpha\", \"##\" .. CFG.prefix .. \"_alpha\", 0.3, 1.0, \"%.2f\")\n        GUI:EndMenu()\n    end\n    GUI:Separator()\n\n    if menu_item(\"Lock\", ui.lock) then ui.lock = not ui.lock; save_store() end\n    GUI:Separator()\n\n    for gi,g in ipairs(CFG.groups) do\n        local node = nodes[gi]\n        if GUI:BeginMenu(g.title) then\n            for _,key in ipairs(node.order) do\n                if menu_item(label_of(g, key), node.state[key] == true) then select_only(node, key) end\n            end\n            GUI:EndMenu()\n        end\n    end\n\n    -- 滑条拖动结束后再存一次，避免拖动中每帧写文件\n    if RG.__ui_dirty[CFG.uiNode] and not GUI:IsAnyItemActive() then\n        RG.__ui_dirty[CFG.uiNode] = false\n        save_store()\n    end\n    GUI:EndPopup()\nend\n\n-- ----- 主窗口 -----\nlocal function draw_panel()\n    local nodes = {}\n    for gi,g in ipairs(CFG.groups) do nodes[gi] = ensure_node(g.node) end\n    local ui     = ensure_ui()\n    if type(ui.showCopy) ~= \"boolean\" then ui.showCopy = false end\n    local p      = ui.per[ui.style]\n    local S      = math.max(0.5, math.min(2.0, p.scale))\n    local locked = ui.lock\n    local compact = (ui.style == \"Compact\")\n\n    local flags = GUI.WindowFlags_AlwaysAutoResize + GUI.WindowFlags_NoScrollbar\n                + GUI.WindowFlags_NoTitleBar + GUI.WindowFlags_NoCollapse\n    if locked then flags = flags + GUI.WindowFlags_NoMove end\n\n    local goldBorder = locked and compact\n    GUI:PushStyleVar(GUI.StyleVar_Alpha, math.max(0.3, math.min(1.0, p.alpha)))\n    GUI:PushStyleVar(GUI.StyleVar_WindowBorderSize, goldBorder and math.max(1, p.border) or p.border)\n    if goldBorder then GUI:PushStyleColor(GUI.Col_Border, 0.88, 0.71, 0.30, 1.0) end\n    GUI:PushStyleVar(GUI.StyleVar_WindowPadding, (compact and 8 or 10)*S, (compact and 6 or 8)*S)\n    GUI:PushStyleVar(GUI.StyleVar_WindowRounding, 8)\n    GUI:PushStyleVar(GUI.StyleVar_FrameRounding, 5)\n    GUI:PushStyleVar(GUI.StyleVar_ItemSpacing, GAP*S, GAP*S)\n    GUI:Begin(\"Role Panel###\" .. CFG.id, true, flags)\n    GUI:SetWindowFontScale(S)\n    local padY = math.max(0, (CELL_H*S - GUI:GetTextLineHeight()) / 2)\n    GUI:PushStyleVar(GUI.StyleVar_FramePadding, 6*S, padY)\n\n    if compact then\n        draw_compact(nodes, S, locked)\n    else\n        draw_header(ui, S)\n        GUI:Separator()\n        if ui.style == \"Modern\" then\n            draw_modern(nodes, S, locked)\n        else\n            draw_classic(nodes, S, locked)\n        end\n        if ui.showCopy then\n            GUI:Separator()\n            draw_copy_section(S)\n        end\n        GUI:Dummy((LABEL_W + ROW_W)*S, 0)\n    end\n\n    draw_context_menu(ui, nodes)\n    GUI:PopStyleVar() -- FramePadding\n    GUI:End()\n    if goldBorder then GUI:PopStyleColor() end\n    GUI:PopStyleVar(6)\nend\n\ndraw_panel()\nself.used = true\n",
