						category = "Lua",
						conditionLua = "-- Role Panel 的 Condition Lua 示例（全部注释，作为文档；也可在面板底部 Copy Condition Lua 一键复制）\n\n-- ===== Tank · RoleMit =====\n-- 当前是 MT\n-- return (RikuduoGadget and RikuduoGadget.is and RikuduoGadget.is(\"MT\")) or false\n\n-- 当前是 ST\n-- return (RikuduoGadget and RikuduoGadget.is and RikuduoGadget.is(\"ST\")) or false\n\n-- 当前是 Manual\n-- return (RikuduoGadget and RikuduoGadget.is and RikuduoGadget.is(\"Manual\")) or false\n\n-- 当前是 MT 或 ST\n-- return (RikuduoGadget and RikuduoGadget.is and (RikuduoGadget.is(\"MT\") or RikuduoGadget.is(\"ST\"))) or false\n\n-- ===== Tank · GroupMit =====\n-- 当前是 MTgroup\n-- return (RikuduoGadget and RikuduoGadget.group_is and RikuduoGadget.group_is(\"MTgroup\")) or false\n\n-- 当前是 STgroup\n-- return (RikuduoGadget and RikuduoGadget.group_is and RikuduoGadget.group_is(\"STgroup\")) or false\n\n-- 当前是 Manualgroup\n-- return (RikuduoGadget and RikuduoGadget.group_is and RikuduoGadget.group_is(\"Manualgroup\")) or false\n\n-- 当前是 MTgroup 或 STgroup\n-- return (RikuduoGadget and RikuduoGadget.group_is and (RikuduoGadget.group_is(\"MTgroup\") or RikuduoGadget.group_is(\"STgroup\"))) or false\n\n-- ===== Healer =====\n-- 当前是 H1\n-- return (RikuduoGadget and RikuduoGadget.healer_is and RikuduoGadget.healer_is(\"H1\")) or false\n\n-- 当前是 H2\n-- return (RikuduoGadget and RikuduoGadget.healer_is and RikuduoGadget.healer_is(\"H2\")) or false\n\n-- 当前是 Manual\n-- return (RikuduoGadget and RikuduoGadget.healer_is and RikuduoGadget.healer_is(\"Manual\")) or false\n\n-- 当前是 H1 或 H2\n-- return (RikuduoGadget and RikuduoGadget.healer_is and (RikuduoGadget.healer_is(\"H1\") or RikuduoGadget.healer_is(\"H2\"))) or false\n\n-- ===== DPS =====\n-- 当前是 D1\n-- return (RikuduoGadget and RikuduoGadget.dps_is and RikuduoGadget.dps_is(\"D1\")) or false\n\n-- 当前是 D2\n-- return (RikuduoGadget and RikuduoGadget.dps_is and RikuduoGadget.dps_is(\"D2\")) or false\n\n-- 当前是 D3\n-- return (RikuduoGadget and RikuduoGadget.dps_is and RikuduoGadget.dps_is(\"D3\")) or false\n\n-- 当前是 D4\n-- return (RikuduoGadget and RikuduoGadget.dps_is and RikuduoGadget.dps_is(\"D4\")) or false\n\n-- 当前是 Manual\n-- return (RikuduoGadget and RikuduoGadget.dps_is and RikuduoGadget.dps_is(\"Manual\")) or false\n\n-- 近战位（D1 或 D2）\n-- return (RikuduoGadget and RikuduoGadget.dps_is and (RikuduoGadget.dps_is(\"D1\") or RikuduoGadget.dps_is(\"D2\"))) or false\n\n-- 远程位（D3 或 D4）\n-- return (RikuduoGadget and RikuduoGadget.dps_is and (RikuduoGadget.dps_is(\"D3\") or RikuduoGadget.dps_is(\"D4\"))) or false\n",
