	{
		data = 
		{
			actions = 
			{
				
				{
					data = 
					{
						aType = "Lua",
						actionLua = "--=========================================================\n-- Weave Mits Hotbar (OnDraw) 图标栏版\n-- 每组显示第一个减伤技能的图标（PNG 在 LuaMods\\RikuWeaveMitsIcons）；左下角标 = 组合内已学会技能的减伤数字之和（如 15+10=25）。\n-- 左键单击：执行组合；按住图标拖动：移动窗口（右键菜单「锁定 hotbar」后不能拖动）。\n-- 右键：设置菜单（缩放、每行个数、背景透明度、锁定）；执行中右键图标=停止队列。\n-- 无敌单击即放（红框标出）。\n-- 小图标：右上=组合里的第二个减伤，15% 短减放右上（右上已占用则左上）；变暗=它在CD或未学会。\n-- 状态：正常=可用  右下橙点=部分在CD(会跳过)  扇形遮罩+秒数=最后一步在CD\n--       白框=执行中  整格变暗=第一个技能未学会\n-- 队列由 [ForCasual] Weave Mits Logic 逐个释放。\n-- 第二个窗口「<职业> 队友」：给队友的减伤，左下角标 LW。点击时选目标：\n--   等效血量 = 血量% / (1 + 权重 x 易伤/流血总层数)，选最低的；相同时按职能（奶妈 > DPS > 坦克）。\n--   不含自己、需在技能射程内；剩余不到 1.5 秒的 debuff 不计。权重在队友窗口右键菜单调整（默认 0.25）。\n--   身上已有该技能 buff（剩余 >= 2 秒）的队友跳过，选下一候补；所有人都有时不放（按钮变暗）。\n-- step = { ids = {升级版, 原版, ...}, skip = 在CD中时是否跳过 }\n--=========================================================\nlocal player = TensorCore.mGetPlayer()\nif not player then return end\n\nlocal hb = data.riku_hotbar\nif not (hb and hb.v == 36) then\n    hb = {\n        v = 36,\n        active = false, queue = nil, idx = 1,\n        startedAt = 0, nextAt = 0, pendingID = 0, pendingAt = 0,\n        ignoreWeave = false, allowInterrupt = false,\n        stateAt = 0, stateJob = 0, states = {},\n        angs = {},\n    }\n    data.riku_hotbar = hb\n\n    local function S(skip, ...) return { ids = { ... }, skip = skip } end\n    local function Q(name, key, ignoreWeave, steps, hold)\n        return { name = name, key = key, ignoreWeave = ignoreWeave,\n                 allowInterrupt = true, steps = steps, hold = hold }  -- 允许打断正在读条的技能\n    end\n\n    hb.jobs = {\n        [19] = { title = \"PLD\", entries = { -- PLD\n            Q(\"15+10\",    \"10\", true, { S(true, 22), S(false, 25746, 3542) }),\n            Q(\"15+20\",    \"20\", true, { S(true, 7531), S(false, 25746, 3542) }),\n            Q(\"15+10+20\", \"30\", true, { S(true, 7531), S(true, 22), S(false, 25746, 3542) }),\n            Q(\"15+40\",    \"40\", true, { S(true, 36920, 17), S(false, 25746, 3542) }),\n            Q(\"Invuln\",   nil,  true,  { S(false, 30) }, true),\n        } },\n        [21] = { title = \"WAR\", entries = { -- WAR\n            Q(\"15+10\",    \"10\", true, { S(true, 40), S(false, 25751, 3551) }),\n            Q(\"15+20\",    \"20\", true, { S(true, 7531), S(false, 25751, 3551) }),\n            Q(\"15+10+20\", \"30\", true, { S(true, 7531), S(true, 40), S(false, 25751, 3551) }),\n            Q(\"15+40\",    \"40\", true, { S(true, 36923, 44), S(false, 25751, 3551) }),\n            Q(\"Invuln\",   nil,  true,  { S(false, 43) }, true),\n        } },\n        [32] = { title = \"DRK\", entries = { -- DRK\n            Q(\"15+10\",    \"10\", true, { S(true, 25754), S(false, 7393) }),\n            Q(\"15+20\",    \"20\", true, { S(true, 7531), S(false, 7393) }),\n            Q(\"15+10+20\", \"30\", true, { S(true, 7531), S(true, 3634), S(true, 25754), S(false, 7393) }),\n            Q(\"15+40\",    \"40\", true, { S(true, 36927, 3636), S(true, 25754), S(false, 7393) }),\n            Q(\"Invuln\",   nil,  true,  { S(false, 3638) }, true),\n        } },\n        [37] = { title = \"GNB\", entries = { -- GNB\n            Q(\"15+10\",    \"10\", true, { S(true, 16140), S(false, 25758, 16161) }),\n            Q(\"15+20\",    \"20\", true, { S(true, 7531), S(false, 25758, 16161) }),\n            Q(\"15+10+20\", \"30\", true, { S(true, 7531), S(true, 16140), S(false, 25758, 16161) }),\n            Q(\"15+40\",    \"40\", true, { S(true, 36935, 16148), S(false, 25758, 16161) }),\n            Q(\"Invuln\",   nil,  true,  { S(false, 16152) }, true),\n        } },\n    }\n\n    -- 队友减伤（目标 = hb.partyTarget 选出的队友）\n    hb.pjobs = {\n        [19] = { -- PLD\n            Q(\"Intervention\", \"LW\", true, { S(false, 7382) }),\n            Q(\"Cover\",        \"LW\", true, { S(false, 27) }),\n        },\n        [21] = { -- WAR\n            Q(\"Nascent Flash\", \"LW\", true, { S(false, 16464) }),\n        },\n        [32] = { -- DRK\n            Q(\"The Blackest Night\", \"LW\", true, { S(false, 7393) }),\n            Q(\"Oblation\",     \"LW\", true, { S(false, 25754) }),\n            Q(\"Oblation + TBN\", \"LW\", true, { S(true, 25754), S(false, 7393) }),\n        },\n        [37] = { -- GNB\n            Q(\"Heart of Corundum\", \"LW\", true, { S(false, 25758, 16161) }),\n            Q(\"Aurora\",       \"LW\", true, { S(false, 16151) }),\n            Q(\"Aurora + HoC\", \"LW\", true, { S(true, 16151), S(false, 25758, 16161) }),\n        },\n    }\n\n    -- 易伤（Vulnerability Up）/ 流血（Bleeding）类状态 ID（Status 表；不含 691 预兆标记）\n\n    hb.debuffSet = {}\n    hb.debuffs = {\n        56, 60, 64, 126, 200, 202, 273, 320, 339, 343, 444, 493, 494, 563, 638, 642,\n        643, 657, 658, 695, 714, 806, 893, 934, 940, 1054, 1074, 1138, 1208, 1402,\n        1412, 1597, 1714, 1789, 1845, 2088, 2090, 2091, 2213, 2347, 2399, 2432, 2636,\n        2912, 2922, 2940, 2941, 2951, 3077, 3078, 3361, 3366, 3414, 3415, 3516, 3536,\n        3557, 3966, 4068, 4137, 4138, 4162, 4375, 5180, 5181, 5442, 5501,\n    }\n\n    for _, id in ipairs(hb.debuffs) do hb.debuffSet[id] = true end\n\n    -- 职能优先级（ClassJob 表 Role 列：1=坦克 4=奶妈，其余 DPS）：奶妈 3 > DPS 2 > 坦克 1\n    hb.rolePri = {\n        [1] = 1, [3] = 1, [19] = 1, [21] = 1, [32] = 1, [37] = 1,\n        [6] = 3, [24] = 3, [28] = 3, [33] = 3, [40] = 3,\n    }\n    hb.roleName = { [1] = \"Tank\", [2] = \"DPS\", [3] = \"Healer\" }\n\n    -- 队友技能 -> 它给目标挂的状态 ID（Status 表同名各版本都列入）\n    hb.applies = {\n        [7382] = { 1174, 2020 },               -- Intervention\n        [27] = { 81, 1301, 2413, 4352 },       -- Cover -> Covered\n        [16464] = { 1858, 2062 },              -- Nascent Flash -> Nascent Glint\n        [7393] = { 1178, 1308 },               -- The Blackest Night -> Blackest Night\n        [25754] = { 2682 },                    -- Oblation\n        [25758] = { 2683, 4295, 1840 },        -- Heart of Corundum（与 Heart of Stone 互通）\n        [16161] = { 1840, 2683, 4295 },        -- Heart of Stone\n        [16151] = { 1835, 2065 },              -- Aurora\n    }\n\n    -- 一组队友技能的“已有就跳过”状态集合（组合里所有技能的状态）\n    function hb.skipSetFor(self, entry)\n        if entry.skipSet then return entry.skipSet end\n        local set = {}\n        for k = 1, #entry.steps do\n            for _, id in ipairs(entry.steps[k].ids) do\n                for _, st in ipairs(self.applies[id] or {}) do set[st] = true end\n            end\n        end\n        entry.skipSet = set\n        return set\n    end\n\n    -- 队友身上是否已有该技能的 buff（剩余 >= 2 秒，或没有倒计时）\n    function hb.hasApplied(self, e, set)\n        if not set or type(e.buffs) ~= \"table\" then return false end\n        for _, b in pairs(e.buffs) do\n            if type(b) == \"table\" and set[b.id] then\n                local d = b.duration or 0\n                if d <= 0 or d >= 2 then return true end\n            end\n        end\n        return false\n    end\n\n    -- 易伤/流血总层数：不叠层的按 1 层；剩余不到 1.5 秒的不计（没有倒计时的 duration=0，计入）\n    function hb.debuffStacks(self, e)\n        local n = 0\n        local buffs = e.buffs\n        if type(buffs) ~= \"table\" then return 0 end\n        for _, b in pairs(buffs) do\n            if type(b) == \"table\" and self.debuffSet[b.id] then\n                local d = b.duration or 0\n                if d <= 0 or d >= 1.5 then\n                    n = n + math.max(1, b.stacks or 0)\n                end\n            end\n        end\n        return n\n    end\n\n    -- 选队友：射程内、活着、不含自己。\n    -- 等效血量 = 血量% / (1 + 权重 x debuff 层数)，最低的优先；等效血量（整数）相同时按职能（奶妈 > DPS > 坦克）\n    function hb.partyTarget(self, range, playerID, skipSet)\n        local list = TensorCore.getEntityGroupList(\"Party\")\n        if not list then return nil end\n        local skipped = 0\n        local w = self.cfg.dWeight or 0.25\n        local best, bestEff, bestRole, bestStacks = nil, 1e9, 0, 0\n        for _, e in pairs(list) do\n            if type(e) == \"table\" and e.id ~= playerID and e.alive and e.hp\n                and (e.distance or 999) <= range and self:hasApplied(e, skipSet) then\n                skipped = skipped + 1\n            elseif type(e) == \"table\" and e.id ~= playerID and e.alive and e.hp\n                and (e.distance or 999) <= range then\n                local stacks = self:debuffStacks(e)\n                local role = self.rolePri[e.job] or 2\n                local eff = math.floor((e.hp.percent or 100) / (1 + w * stacks))\n                if best == nil or eff < bestEff or (eff == bestEff and role > bestRole) then\n                    best, bestEff, bestRole, bestStacks = e, eff, role, stacks\n                end\n            end\n        end\n        return best, bestStacks, bestRole, bestEff, skipped\n    end\n\n    -- 队友减伤一组的状态：在 entryState 基础上加目标和射程\n    function hb.partyState(self, entry, level, s, playerID)\n        self:entryState(entry, level, s)\n        -- 组合技：右上 1/4 显示另一个技能（最后一步）的图标\n        if not s.tex2 and #entry.steps >= 2 then s.tex2, s.ok2 = s.tex15, s.ok15 end\n        s.tex15, s.ok15, s.label = nil, false, \"LW\"\n        local range = 999\n        for k = 1, #entry.steps do\n            local ids = entry.steps[k].ids\n            for j = 1, #ids do\n                local a = ActionList:Get(1, ids[j])\n                if a and a.level <= level then\n                    if a.range and a.range > 0 and a.range < range then range = a.range end\n                    break\n                end\n            end\n        end\n        s.range = range\n        local t, stacks, role, eff, skipped = self:partyTarget(range, playerID, self:skipSetFor(entry))\n        s.tgt = t and t.id or nil\n        if t then\n            s.tgtText = \"Target: \" .. tostring(t.name) .. \" (\" .. (self.roleName[role] or \"?\") .. \")  \"\n                .. math.floor(t.hp.percent or 0) .. \"%\"\n                .. ((stacks or 0) > 0 and (\"  [Vuln/Bleed x\" .. stacks .. \"]  effective \" .. eff .. \"%\") or \"\")\n        else\n            s.tgtText = ((skipped or 0) > 0) and \"Target: everyone in range already has it\"\n                or \"Target: no party member in range\"\n        end\n        s.tgtDeb = (stacks or 0) > 0\n    end\n\n    -- 图标 PNG 由客户端 ui/icon/*_hr1.tex 导出，文件名 = 图标 ID\n    hb.iconDir = GetLuaModsPath() .. \"RikuWeaveMitsIcons\\\\round\\\\\"\n    -- 技能 ID -> 图标 ID（Action 表 Icon 列）\n    hb.icons = {\n        [22] = 167, [7531] = 801, [36920] = 2524, [17] = 151, [30] = 2502,\n        [40] = 263, [36923] = 2573, [44] = 267, [43] = 266,\n        [25754] = 3089, [36927] = 3094, [3636] = 3075, [3638] = 3077,\n        [16140] = 3404, [36935] = 3435, [16148] = 3412, [16152] = 3416,\n        [3634] = 3076,\n        [25746] = 2950, [3542] = 2510, [25751] = 2569, [3551] = 2559,\n        [7393] = 3081, [25758] = 3430, [16161] = 3425,\n        [7382] = 2512, [27] = 2501, [16464] = 2567, [16151] = 3415, [3541] = 2509,\n    }\n\n    -- 技能 ID -> 英文名（Action 表 English）\n    hb.ename = {\n        [17] = \"Sentinel\", [22] = \"Bulwark\", [27] = \"Cover\", [30] = \"Hallowed Ground\",\n        [40] = \"Thrill of Battle\", [43] = \"Holmgang\", [44] = \"Vengeance\",\n        [3541] = \"Clemency\", [3542] = \"Sheltron\", [3551] = \"Raw Intuition\",\n        [3634] = \"Dark Mind\", [3636] = \"Shadow Wall\", [3638] = \"Living Dead\",\n        [7382] = \"Intervention\", [7393] = \"The Blackest Night\", [7531] = \"Rampart\",\n        [16140] = \"Camouflage\", [16148] = \"Nebula\", [16151] = \"Aurora\",\n        [16152] = \"Superbolide\", [16161] = \"Heart of Stone\", [16464] = \"Nascent Flash\",\n        [25746] = \"Holy Sheltron\", [25751] = \"Bloodwhetting\", [25754] = \"Oblation\",\n        [25758] = \"Heart of Corundum\", [36920] = \"Guardian\", [36923] = \"Damnation\",\n        [36927] = \"Shadowed Vigil\", [36935] = \"Great Nebula\",\n    }\n\n    -- 技能 ID -> 角标里计入的减伤数字\n    hb.mit = {\n        [25746] = 15, [3542] = 15, [25751] = 15, [3551] = 15,\n        [7393] = 15, [25758] = 15, [16161] = 15,\n        [7531] = 20,\n        [36920] = 40, [17] = 40, [36923] = 40, [44] = 40,\n        [36927] = 40, [3636] = 40, [36935] = 40, [16148] = 40,\n        [22] = 10, [40] = 10, [3634] = 10, [25754] = 10, [16140] = 10,\n    }\n\n    hb.col = {\n        shadow = GUI:GetColorU32(0, 0, 0, 0.9),\n        text   = GUI:GetColorU32(1, 0.96, 0.82, 1),\n        stroke = GUI:GetColorU32(0, 0, 0, 1),\n        dim    = GUI:GetColorU32(0, 0, 0, 0.72),\n        orange = GUI:GetColorU32(0.94, 0.64, 0.16, 1),\n        white  = GUI:GetColorU32(1, 1, 1, 1),\n        hover  = GUI:GetColorU32(1, 1, 1, 0.12),\n        bg     = GUI:GetColorU32(0.12, 0.13, 0.16, 1),\n        invEdge = GUI:GetColorU32(0.55, 0.12, 0.12, 1),\n        outline = GUI:GetColorU32(0, 0, 0, 0.9),\n        drop1   = GUI:GetColorU32(0, 0, 0, 0.22),\n        drop2   = GUI:GetColorU32(0, 0, 0, 0.45),\n        gloss   = GUI:GetColorU32(1, 1, 1, 0.28),\n        debEdge = GUI:GetColorU32(0.85, 0.25, 0.85, 1),\n    }\n    local PI2 = math.pi * 2\n\n    -- 取当前真正可用的版本（升级版在前），返回 action 和对应 ID。\n    -- 572 = \"Cannot use yet.\"：未学会或已被升级替换（等级同步时也成立）\n    function hb.pick(ids, level)\n        for i = 1, #ids do\n            local a = ActionList:Get(1, ids[i])\n            if a and a.level <= level and a:CanCastResult() ~= 572 then return a, ids[i] end\n        end\n        return nil\n    end\n\n    -- 一组的状态写进 s：st 1=可用 2=部分在CD 3=最后一步在CD；wait 秒；frac 已冷却比例；tex 图标；learned；tip\n    function hb.entryState(self, entry, level, s)\n        local steps = entry.steps\n        local st, wait, frac = 1, 0, 0\n        local lines = {}\n        local a1, id1 = self.pick(steps[1].ids, level)\n        local ids1 = steps[1].ids\n        local icon = self.icons[id1 or ids1[#ids1]]\n        s.tex = icon and (self.iconDir .. icon .. \".png\") or nil\n        -- 小图标：组合里的第二个减伤（右上），以及最后的 15% 短减\n        local function mini(ids)\n            local a, id = self.pick(ids, level)\n            local ic = self.icons[id or ids[#ids]]\n            return ic and (self.iconDir .. ic .. \".png\") or nil,\n                   a ~= nil and not (a.isoncd and not a:IsReady())\n        end\n        s.tex2, s.ok2 = nil, false\n        if #steps >= 3 then s.tex2, s.ok2 = mini(steps[2].ids) end\n        s.tex15, s.ok15 = nil, false\n        -- 角标 = 组合内已学会技能的减伤数字之和（只看等级；量谱不足等暂时不能用的也计入）\n        local sum = 0\n        for k = 1, #steps do\n            local ids = steps[k].ids\n            for j = 1, #ids do\n                local a = ActionList:Get(1, ids[j])\n                if a and a.level <= level then\n                    sum = sum + (self.mit[ids[j]] or 0)\n                    break\n                end\n            end\n        end\n        s.label = (entry.key and sum > 0) and tostring(sum) or nil\n        if entry.key then s.tex15, s.ok15 = mini(steps[#steps].ids) end\n        s.learned = a1 ~= nil\n        for i = 1, #steps do\n            local step = steps[i]\n            local a, aid = self.pick(step.ids, level)\n            if a == nil then\n                local bid = step.ids[#step.ids]\n                local base = ActionList:Get(1, bid)\n                lines[#lines + 1] = (self.ename[bid] or (base and base.name) or tostring(bid)) .. \"  unavailable\"\n            else\n                local onCD = a.isoncd and not a:IsReady()\n                local an = self.ename[aid] or a.name\n                if onCD then\n                    local remain = math.ceil(math.max(0, a.cdmax - a.cd))\n                    if step.skip then\n                        if st < 2 then st = 2 end\n                        lines[#lines + 1] = an .. \"  CD \" .. remain .. \"s (skip)\"\n                    else\n                        st = 3\n                        if remain > wait then\n                            wait = remain\n                            frac = (a.cdmax > 0) and (a.cd / a.cdmax) or 0\n                        end\n                        lines[#lines + 1] = an .. \"  CD \" .. remain .. \"s\"\n                    end\n                else\n                    lines[#lines + 1] = an .. \"  ready\"\n                end\n            end\n        end\n        s.st, s.wait, s.frac, s.tip = st, wait, frac, table.concat(lines, \"\\n\")\n    end\n\n    -- 顺时针扇形遮罩：从 frac 处画到 12 点方向，覆盖还没冷却完的部分；沿圆角矩形（半径 r）边缘\n    function hb.sweep(self, x1, y1, x2, y2, frac, col, r)\n        local cx, cy, h = (x1 + x2) * 0.5, (y1 + y2) * 0.5, (x2 - x1) * 0.5\n        r = math.min(r or 0, h)\n        local a0 = frac * PI2\n        local angs = self.angs\n        local n = 1\n        angs[1] = a0\n        local STEP = PI2 / 32\n        local k0 = math.floor(a0 / STEP) + 1\n        for k = k0, 31 do n = n + 1; angs[n] = k * STEP end\n        n = n + 1; angs[n] = PI2\n        local e = h - r\n        local function pt(t)\n            local dx, dy = math.sin(t), -math.cos(t)\n            local m = math.max(math.abs(dx), math.abs(dy))\n            local ox, oy = dx / m * h, dy / m * h\n            -- 落在圆角区域时投影到圆弧上\n            if r > 0 and math.abs(ox) > e and math.abs(oy) > e then\n                local ccx = (ox > 0) and e or -e\n                local ccy = (oy > 0) and e or -e\n                local vx, vy = ox - ccx, oy - ccy\n                local len = math.sqrt(vx * vx + vy * vy)\n                if len > 0 then ox, oy = ccx + vx / len * r, ccy + vy / len * r end\n            end\n            return cx + ox, cy + oy\n        end\n        local px, py = pt(angs[1])\n        for k = 2, n do\n            local qx, qy = pt(angs[k])\n            GUI:AddTriangleFilled(cx, cy, px, py, qx, qy, col)\n            px, py = qx, qy\n        end\n    end\n\n    -- 设置（缩放、每行个数、背景透明度）存在 Rikuduo_s_Gadgets\\Settings\\WeaveMitsHotbar.lua\n    local SAVE_DIR = [[TensorReactions\\GeneralReactions\\Rikuduo_s_Gadgets\\Settings\\]]\n    local SAVE_REL = SAVE_DIR .. [[WeaveMitsHotbar.lua]]\n    local path = GetLuaModsPath() .. SAVE_REL\n    local saved = FileExists(path) and FileLoad(path) or nil\n    if type(saved) ~= \"table\" then saved = {} end\n    hb.cfg = {\n        scale = (type(saved.scale) == \"number\") and saved.scale or 1.0,\n        perRow = (type(saved.perRow) == \"number\") and saved.perRow or 5,\n        bgAlpha = (type(saved.bgAlpha) == \"number\") and saved.bgAlpha or 0.55,\n        pScale = (type(saved.pScale) == \"number\") and saved.pScale or 1.0,\n        pPerRow = (type(saved.pPerRow) == \"number\") and saved.pPerRow or 5,\n        pBgAlpha = (type(saved.pBgAlpha) == \"number\") and saved.pBgAlpha or 0.55,\n        locked = saved.locked == true,\n        dWeight = (type(saved.dWeight) == \"number\") and saved.dWeight or 0.25,\n    }\n    hb.pstates = {}\n    hb.cfgDirty = false\n    function hb.saveCfg(self)\n        local base = GetLuaModsPath()\n        if not FolderExists(base .. SAVE_DIR) then FolderCreate(base .. SAVE_DIR) end\n        FileSave(base .. SAVE_REL, self.cfg)\n    end\n\n    function hb.dragWin(self, win, hoverIdx, onClick)\n        local d = self.drag\n        if not (d and d.win == win) then return end\n        local mx, my = GUI:GetMousePos()\n        if GUI:IsMouseDown(0) then\n            if not d.moved and not self.cfg.locked\n                and (math.abs(mx - d.px) > 4 or math.abs(my - d.py) > 4) then\n                d.moved = true\n            end\n            if d.moved then GUI:SetWindowPos(mx - d.ox, my - d.oy) end\n        else\n            if not d.moved and hoverIdx == d.idx then onClick(d.idx) end\n            self.drag = nil\n        end\n    end\n\n    -- 图标上按下左键：记录按下位置和相对窗口的偏移\n    function hb.press(self, win, idx)\n        local mx, my = GUI:GetMousePos()\n        local wx, wy = GUI:GetWindowPos()\n        self.drag = { win = win, idx = idx, px = mx, py = my, ox = mx - wx, oy = my - wy, moved = false }\n    end\n\n    -- 菜单超出屏幕（窗口在屏幕底部/右侧时）就移回屏幕内\n    function hb.clampToScreen()\n        local wx, wy = GUI:GetWindowPos()\n        local ww, wh = GUI:GetWindowSize()\n        local sw, sh = GUI:GetScreenSize()\n        local nx = math.max(0, math.min(wx, sw - ww - 4))\n        local ny = math.max(0, math.min(wy, sh - wh - 4))\n        if nx ~= wx or ny ~= wy then GUI:SetWindowPos(nx, ny) end\n    end\n\n    function hb.start(self, entry, targetID)\n        self.active = true\n        self.targetID = targetID\n        self.queue = entry\n        self.idx = 1\n        self.startedAt = Now()\n        self.nextAt = 0\n        self.ignoreWeave = entry.ignoreWeave\n        self.allowInterrupt = entry.allowInterrupt\n        self.pendingID = 0\n        self.pendingAt = 0\n    end\n\n    function hb.stop(self)\n        self.active = false\n        self.targetID = nil\n        self.queue = nil\n        self.idx = 1\n        self.pendingID = 0\n        self.pendingAt = 0\n    end\nend\n\nlocal cfg = hb.jobs[player.job]\nif not cfg then return end\nlocal entries = cfg.entries\nlocal now = Now()\n\n-- 状态每 250ms 刷新一次，不在每帧查技能\nif now - hb.stateAt > 250 or hb.stateJob ~= player.job then\n    hb.stateAt = now\n    hb.stateJob = player.job\n    local level = player.level\n    for i = 1, #entries do\n        local s = hb.states[i] or {}\n        hb:entryState(entries[i], level, s)\n        hb.states[i] = s\n    end\n    local pe = hb.pjobs[player.job]\n    if pe then\n        for i = 1, #pe do\n            local s = hb.pstates[i] or {}\n            hb:partyState(pe[i], level, s, player.id)\n            hb.pstates[i] = s\n        end\n    end\nend\n\nlocal C = hb.col\nlocal cfgv = hb.cfg\nlocal scale = cfgv.scale\nlocal perRow = math.max(1, math.min(cfgv.perRow, #entries))\nlocal SZ = math.floor(30 * scale + 0.5)\nlocal R = SZ * 0.16\nlocal flags = GUI.WindowFlags_NoTitleBar + GUI.WindowFlags_AlwaysAutoResize\n    + GUI.WindowFlags_NoScrollbar + GUI.WindowFlags_NoFocusOnAppearing\nif cfgv.locked then flags = flags + GUI.WindowFlags_NoMove end\n\n-- 描边字（参考游戏技能栏）：黑色描边 + 米白字，描边粗细随缩放\nlocal stroke = (scale >= 1.5) and 2 or 1\n-- 左下角标字号：参考 TensorACR 技能栏（字高约为图标的 1/5），1px 描边\nlocal LABEL_FONT = 0.72\nlocal function shadowText(x, y, text, col)\n    for dx = -stroke, stroke do\n        for dy = -stroke, stroke do\n            if dx ~= 0 or dy ~= 0 then GUI:AddText(x + dx, y + dy, C.stroke, text) end\n        end\n    end\n    GUI:AddText(x, y, col, text)\nend\n\nGUI:PushStyleVar(GUI.StyleVar_WindowPadding, 3, 3)\nGUI:PushStyleVar(GUI.StyleVar_ItemSpacing, 2, 2)\nGUI:PushStyleVar(GUI.StyleVar_FramePadding, 0, 0)\nGUI:PushStyleColor(GUI.Col_WindowBg, 0.03, 0.035, 0.05, cfgv.bgAlpha)\nlocal visible = GUI:Begin(cfg.title, true, flags)\nif visible then\n    GUI:SetWindowFontScale(scale * 1.2)\n    local rightOnItem = false\n    local tipIdx = nil\n    for i = 1, #entries do\n        local e = entries[i]\n        local s = hb.states[i]\n        if (i - 1) % perRow ~= 0 then\n            if e.hold then GUI:SameLine(0, math.floor(6 * scale)) else GUI:SameLine() end\n        end\n\n        GUI:InvisibleButton(\"##wm\" .. i, SZ, SZ)\n        if GUI:IsItemClicked(0) then hb:press(\"main\", i) end\n        if GUI:IsItemClicked(1) then rightOnItem = true end\n        local hovered = GUI:IsItemHovered()\n        local x1, y1 = GUI:GetItemRectMin()\n        local x2, y2 = GUI:GetItemRectMax()\n        -- 投影（右下 1~2px 柔和阴影），参考游戏原生图标\n        GUI:AddRectFilled(x1, y1 + 1, x2 + 2, y2 + 2, C.drop1, R + 1)\n        GUI:AddRectFilled(x1, y1 + 1, x2 + 1, y2 + 1, C.drop2, R)\n        GUI:AddRectFilled(x1, y1, x2, y2, C.bg, R)\n        if s.tex then GUI:AddImage(s.tex, x1, y1, x2, y2) end\n        -- 右上 1/4：第二个减伤；15% 短减放右上，右上已占用时放左上\n        local mx, my = x1 + SZ * 0.5, y1 + SZ * 0.5\n        if s.tex2 then\n            GUI:AddRectFilled(mx - 1, y1, x2, my + 1, C.shadow, R * 0.6)\n            GUI:AddImage(s.tex2, mx, y1, x2, my)\n            if not s.ok2 then GUI:AddRectFilled(mx, y1, x2, my, C.dim, R * 0.5) end\n        end\n        if s.tex15 then\n            local ax1, ax2 = mx, x2\n            if s.tex2 then ax1, ax2 = x1, mx end\n            GUI:AddRectFilled(ax1 - (s.tex2 and 0 or 1), y1, ax2 + (s.tex2 and 1 or 0), my + 1, C.shadow, R * 0.6)\n            GUI:AddImage(s.tex15, ax1, y1, ax2, my)\n            if not s.ok15 then GUI:AddRectFilled(ax1, y1, ax2, my, C.dim, R * 0.5) end\n        end\n\n        if not s.learned then\n            GUI:AddRectFilled(x1, y1, x2, y2, C.dim, R)\n        elseif s.st == 3 then\n            hb:sweep(x1, y1, x2, y2, s.frac, C.dim, R)\n            local t = tostring(s.wait)\n            local tw, th = GUI:CalcTextSize(t)\n            shadowText(x1 + (SZ - tw) * 0.5, y1 + (SZ - th) * 0.5, t, C.text)\n        end\n        if hovered then GUI:AddRectFilled(x1, y1, x2, y2, C.hover, R) end\n        -- 顶部内侧高光 + 1px 黑色外框\n        GUI:AddLine(x1 + R, y1 + 1, x2 - R, y1 + 1, C.gloss)\n        GUI:AddRect(x1, y1, x2, y2, C.outline, R)\n\n        if e.hold then\n            GUI:AddRect(x1, y1, x2, y2, C.invEdge, R)\n            GUI:AddRect(x1 + 1, y1 + 1, x2 - 1, y2 - 1, C.invEdge, R - 1)\n        else\n            if s.st == 2 and s.learned then\n                local r = 3.5 * scale\n                GUI:AddCircleFilled(x2 - r - 1.5, y2 - r - 1.5, r, C.shadow)\n                GUI:AddCircleFilled(x2 - r - 1.5, y2 - r - 1.5, r - 1, C.orange)\n            end\n            if s.st ~= 3 and s.label then\n                local st0 = stroke\n                stroke = 1\n                GUI:SetWindowFontScale(scale * LABEL_FONT)\n                local _, th = GUI:CalcTextSize(s.label)\n                shadowText(x1 + 2, y2 - th + 1, s.label, C.text)\n                GUI:SetWindowFontScale(scale * 1.2)\n                stroke = st0\n            end\n        end\n\n        if hb.active and hb.queue == e then\n            GUI:AddRect(x1, y1, x2, y2, C.white, R)\n            GUI:AddRect(x1 + 1, y1 + 1, x2 - 1, y2 - 1, C.white, R - 1)\n        end\n\n        if hovered then tipIdx = i end\n    end\n    hb:dragWin(\"main\", tipIdx, function(k) hb:start(entries[k]) end)\n    -- 字体缩放只用于图标上的文字；提示和菜单恢复正常大小\n    GUI:SetWindowFontScale(1)\n    if tipIdx then\n        local e, s = entries[tipIdx], hb.states[tipIdx]\n        GUI:SetTooltip(e.name .. \"\\n\" .. s.tip .. \"\\nRight-click: settings (on icon while running = stop)\")\n    end\n\n    -- 右键：执行中点在图标上=停止队列；其余情况打开设置菜单\n    if GUI:IsWindowHovered() and GUI:IsMouseClicked(1) then\n        if rightOnItem and hb.active then\n            hb:stop()\n        else\n            GUI:OpenPopup(\"##wmMenu\")\n        end\n    end\n\n    GUI:PushStyleVar(GUI.StyleVar_WindowPadding, 8, 6)\n    GUI:PushStyleVar(GUI.StyleVar_ItemSpacing, 6, 5)\n    GUI:PushStyleVar(GUI.StyleVar_FramePadding, 4, 3)\n    if GUI:BeginPopup(\"##wmMenu\") then\n        GUI:SetWindowFontScale(1)\n        GUI:TextDisabled(cfg.title .. \" Mits Hotbar\")\n        GUI:PushItemWidth(140)\n        local v, changed = GUI:SliderFloat(\"Scale##wmScale\", cfgv.scale, 0.6, 2.0, \"%.1f\")\n        if changed then cfgv.scale = math.floor(v * 10 + 0.5) / 10; hb.cfgDirty = true end\n        local n, changed2 = GUI:SliderInt(\"Per row##wmRow\", perRow, 1, #entries)\n        if changed2 then cfgv.perRow = n; hb.cfgDirty = true end\n        local a, changed3 = GUI:SliderFloat(\"Background opacity##wmBg\", cfgv.bgAlpha, 0, 1, \"%.2f\")\n        if changed3 then cfgv.bgAlpha = math.floor(a * 100 + 0.5) / 100; hb.cfgDirty = true end\n        GUI:PopItemWidth()\n        -- 出错时记录到 RikuHotbarErr，并保证 EndPopup 仍会调用\n        local okM, errM = pcall(function()\n        GUI:Separator()\n        if GUI:MenuItem(\"Reset to default\", \"\", false, true) then\n            cfgv.scale, cfgv.perRow, cfgv.bgAlpha = 1.0, 5, 0.55\n            hb.cfgDirty = true\n        end\n        if GUI:MenuItem(\"Lock hotbar\", \"\", cfgv.locked, true) then\n            cfgv.locked = not cfgv.locked; hb.cfgDirty = true\n        end\n        if GUI:MenuItem(\"Stop queue\", \"\", false, hb.active) then hb:stop() end\n        hb.clampToScreen()\n        end)\n        if not okM then RikuHotbarErr = tostring(errM) end\n        GUI:EndPopup()\n    elseif hb.cfgDirty then\n        -- 菜单关闭后再写盘，拖动滑条时不反复保存\n        hb.cfgDirty = false\n        hb:saveCfg()\n    end\n    GUI:PopStyleVar(3)\nend\nGUI:End()\nGUI:PopStyleColor(1)\nGUI:PopStyleVar(3)\n\n--=================== 队友减伤窗口 ===================\nlocal pentries = hb.pjobs and hb.pjobs[player.job]\nif not pentries then return end\nlocal pscale = cfgv.pScale\nlocal pPerRow = math.max(1, math.min(cfgv.pPerRow, #pentries))\nlocal PSZ = math.floor(30 * pscale + 0.5)\nlocal R = PSZ * 0.16\nlocal pstroke = (pscale >= 1.5) and 2 or 1\nlocal function pText(x, y, text, col)\n    for dx = -pstroke, pstroke do\n        for dy = -pstroke, pstroke do\n            if dx ~= 0 or dy ~= 0 then GUI:AddText(x + dx, y + dy, C.stroke, text) end\n        end\n    end\n    GUI:AddText(x, y, col, text)\nend\n\nGUI:PushStyleVar(GUI.StyleVar_WindowPadding, 3, 3)\nGUI:PushStyleVar(GUI.StyleVar_ItemSpacing, 2, 2)\nGUI:PushStyleVar(GUI.StyleVar_FramePadding, 0, 0)\nGUI:PushStyleColor(GUI.Col_WindowBg, 0.03, 0.035, 0.05, cfgv.pBgAlpha)\nlocal pvisible = GUI:Begin(cfg.title .. \" Party\", true, flags)\nif pvisible then\n    GUI:SetWindowFontScale(pscale * 1.2)\n    local rightOnItem = false\n    local tipIdx = nil\n    for i = 1, #pentries do\n        local e = pentries[i]\n        local s = hb.pstates[i]\n        if (i - 1) % pPerRow ~= 0 then GUI:SameLine() end\n\n        GUI:InvisibleButton(\"##wmp\" .. i, PSZ, PSZ)\n        if GUI:IsItemClicked(0) then hb:press(\"party\", i) end\n        if GUI:IsItemClicked(1) then rightOnItem = true end\n        local hovered = GUI:IsItemHovered()\n        local x1, y1 = GUI:GetItemRectMin()\n        local x2, y2 = GUI:GetItemRectMax()\n        -- 投影（右下 1~2px 柔和阴影），参考游戏原生图标\n        GUI:AddRectFilled(x1, y1 + 1, x2 + 2, y2 + 2, C.drop1, R + 1)\n        GUI:AddRectFilled(x1, y1 + 1, x2 + 1, y2 + 1, C.drop2, R)\n        GUI:AddRectFilled(x1, y1, x2, y2, C.bg, R)\n        if s.tex then GUI:AddImage(s.tex, x1, y1, x2, y2) end\n        local mx, my = x1 + PSZ * 0.5, y1 + PSZ * 0.5\n        if s.tex2 then\n            GUI:AddRectFilled(mx - 1, y1, x2, my + 1, C.shadow, R * 0.6)\n            GUI:AddImage(s.tex2, mx, y1, x2, my)\n            if not s.ok2 then GUI:AddRectFilled(mx, y1, x2, my, C.dim, R * 0.5) end\n        end\n        -- 没有可用目标 / 未学会 = 整格变暗\n        if not s.learned or not s.tgt then\n            GUI:AddRectFilled(x1, y1, x2, y2, C.dim, R)\n        elseif s.st == 3 then\n            hb:sweep(x1, y1, x2, y2, s.frac, C.dim, R)\n            local t = tostring(s.wait)\n            local tw, th = GUI:CalcTextSize(t)\n            pText(x1 + (PSZ - tw) * 0.5, y1 + (PSZ - th) * 0.5, t, C.text)\n        end\n        if hovered then GUI:AddRectFilled(x1, y1, x2, y2, C.hover, R) end\n        -- 顶部内侧高光 + 1px 黑色外框\n        GUI:AddLine(x1 + R, y1 + 1, x2 - R, y1 + 1, C.gloss)\n        GUI:AddRect(x1, y1, x2, y2, C.outline, R)\n        if s.st == 2 and s.learned then\n            local r = 3.5 * pscale\n            GUI:AddCircleFilled(x2 - r - 1.5, y2 - r - 1.5, r, C.shadow)\n            GUI:AddCircleFilled(x2 - r - 1.5, y2 - r - 1.5, r - 1, C.orange)\n        end\n        if s.st ~= 3 then\n            local st0 = pstroke\n            pstroke = 1\n            GUI:SetWindowFontScale(pscale * LABEL_FONT)\n            local _, th = GUI:CalcTextSize(\"LW\")\n            pText(x1 + 2, y2 - th + 1, \"LW\", C.text)\n            GUI:SetWindowFontScale(pscale * 1.2)\n            pstroke = st0\n        end\n        -- 当前目标身上有易伤/流血：紫框提示\n        if s.tgt and s.tgtDeb then GUI:AddRect(x1, y1, x2, y2, C.debEdge, R) end\n\n        if hb.active and hb.queue == e then\n            GUI:AddRect(x1, y1, x2, y2, C.white, R)\n            GUI:AddRect(x1 + 1, y1 + 1, x2 - 1, y2 - 1, C.white, R - 1)\n        end\n        if hovered then tipIdx = i end\n    end\n    hb:dragWin(\"party\", tipIdx, function(k)\n        local t = hb:partyTarget(hb.pstates[k].range or 30, player.id, hb:skipSetFor(pentries[k]))\n        if t then hb:start(pentries[k], t.id) end\n    end)\n    GUI:SetWindowFontScale(1)\n    if tipIdx then\n        local e, s = pentries[tipIdx], hb.pstates[tipIdx]\n        GUI:SetTooltip(e.name .. \"\\n\" .. (s.tgtText or \"\") .. \"\\n\" .. s.tip\n            .. \"\\nRight-click: settings (on icon while running = stop)\")\n    end\n\n    if GUI:IsWindowHovered() and GUI:IsMouseClicked(1) then\n        if rightOnItem and hb.active then\n            hb:stop()\n        else\n            GUI:OpenPopup(\"##wmPMenu\")\n        end\n    end\n\n    GUI:PushStyleVar(GUI.StyleVar_WindowPadding, 8, 6)\n    GUI:PushStyleVar(GUI.StyleVar_ItemSpacing, 6, 5)\n    GUI:PushStyleVar(GUI.StyleVar_FramePadding, 4, 3)\n    if GUI:BeginPopup(\"##wmPMenu\") then\n        GUI:SetWindowFontScale(1)\n        GUI:TextDisabled(cfg.title .. \" Party Mits Hotbar\")\n        GUI:PushItemWidth(140)\n        local v, changed = GUI:SliderFloat(\"Scale##wmpScale\", cfgv.pScale, 0.6, 2.0, \"%.1f\")\n        if changed then cfgv.pScale = math.floor(v * 10 + 0.5) / 10; hb.pcfgDirty = true end\n        local n, changed2 = GUI:SliderInt(\"Per row##wmpRow\", pPerRow, 1, #pentries)\n        if changed2 then cfgv.pPerRow = n; hb.pcfgDirty = true end\n        local a, changed3 = GUI:SliderFloat(\"Background opacity##wmpBg\", cfgv.pBgAlpha, 0, 1, \"%.2f\")\n        if changed3 then cfgv.pBgAlpha = math.floor(a * 100 + 0.5) / 100; hb.pcfgDirty = true end\n        local dw, changed4 = GUI:SliderFloat(\"Debuff weight##wmpDw\", cfgv.dWeight, 0, 1, \"%.2f\")\n        if changed4 then cfgv.dWeight = math.floor(dw * 100 + 0.5) / 100; hb.pcfgDirty = true end\n        GUI:PopItemWidth()\n        -- 出错时记录到 RikuHotbarErr，并保证 EndPopup 仍会调用\n        local okM, errM = pcall(function()\n        GUI:Separator()\n        if GUI:MenuItem(\"Reset to default\", \"\", false, true) then\n            cfgv.pScale, cfgv.pPerRow, cfgv.pBgAlpha, cfgv.dWeight = 1.0, 5, 0.55, 0.25\n            hb.pcfgDirty = true\n        end\n        if GUI:MenuItem(\"Lock hotbar\", \"\", cfgv.locked, true) then\n            cfgv.locked = not cfgv.locked; hb.pcfgDirty = true\n        end\n        if GUI:MenuItem(\"Stop queue\", \"\", false, hb.active) then hb:stop() end\n        hb.clampToScreen()\n        end)\n        if not okM then RikuHotbarErr = tostring(errM) end\n        GUI:EndPopup()\n    elseif hb.pcfgDirty then\n        hb.pcfgDirty = false\n        hb:saveCfg()\n    end\n    GUI:PopStyleVar(3)\nend\nGUI:End()\nGUI:PopStyleColor(1)\nGUI:PopStyleVar(3)\n",
