	{
		data = 
		{
			actions = 
			{
				
				{
					data = 
					{
						aType = "Lua",
						actionLua = "--=========================================================\n-- Weave Mits Logic (OnFrame)\n-- 执行 [ForCasual] Weave Mits Hotbar 写入 data.riku_hotbar 的减伤队列。\n-- step = { ids = {升级版, 原版, ...}, skip = 在CD中时是否跳过 }\n-- 返回: action, targetID(自己，或队友窗口选中的 hb.targetID), ignoreWeaveRules, allowInterrupt\n--=========================================================\nlocal hb = data.riku_hotbar\nif not (hb and hb.active and hb.queue and hb.stop and hb.pick) then return end\n\nlocal now = Now()\nif now < hb.nextAt then return end\n\n-- 安全超时：整条队列 10 秒（waitCast 的读条技能不限时，右键图标可停止）\nif not hb.queue.waitCast and now - hb.startedAt > 10000 then\n    hb:stop()\n    return\nend\n\nlocal player = TensorCore.mGetPlayer()\nif not player then return end\n\n-- 目标：队友减伤窗口会写 hb.targetID；队友死亡/消失则停止\nlocal tid = player.id\nif hb.targetID then\n    local t = TensorCore.mGetEntity(hb.targetID)\n    if not (t and t.alive) then\n        hb:stop()\n        return\n    end\n    tid = t.id\nend\n\nlocal steps = hb.queue.steps\nlocal act\nwhile hb.idx <= #steps do\n    local step = steps[hb.idx]\n    -- 取当前真正可用的版本（升级版在前，同一冷却组；见 Hotbar 的 hb.pick）\n    act = hb.pick(step.ids, player.level)\n    if act == nil\n        or (step.skip and hb.pendingID ~= act.id and act.isoncd and not act:IsReady(tid)) then\n        hb.idx = hb.idx + 1\n        hb.pendingID = 0\n    else\n        break\n    end\nend\n\nif hb.idx > #steps then\n    hb:stop()\n    return\nend\n\n-- 读条技能（queue.waitCast）：一直重试到真正放出为止。\n-- 放出的判定 = MP 比发出请求时少了技能消耗的 3/4 以上（MP 在读条完成时才扣）；\n-- 读条被打断、ACR 占着 GCD 都会继续等，不设超时。目标死亡或右键图标会停止。\nif hb.queue.waitCast then\n    local mp = (player.mp and player.mp.current) or 0\n    local cost = act.cost or 0\n    local ci = player.castinginfo\n    if hb.pendingID == act.id then\n        local done\n        if cost > 0 then\n            done = mp <= hb.waitMP - cost * 0.75\n        else\n            done = ci and ci.lastcastid == act.id and ci.timesincecast < now - hb.pendingAt\n                and ci.channelingid ~= act.id\n        end\n        if done then\n            hb.pendingID = 0\n            hb.idx = hb.idx + 1\n            hb.nextAt = now + 250\n            return\n        end\n        -- 等待期间 MP 自然回复时抬高基准\n        if mp > hb.waitMP then hb.waitMP = mp end\n        -- 正在读条：不再重复发\n        if ci and ci.channelingid == act.id then\n            hb.nextAt = now + 100\n            return\n        end\n    end\n    if not act:IsReady(tid) then\n        hb.nextAt = now + 100\n        return\n    end\n    if hb.pendingID ~= act.id then\n        hb.pendingID = act.id\n        hb.waitMP = mp\n    end\n    hb.pendingAt = now\n    hb.nextAt = now + 100\n    return act, tid, hb.ignoreWeave, hb.allowInterrupt\nend\n\n-- 已发出请求：确认真正放出后再前进\nif hb.pendingID == act.id then\n    local ci = player.castinginfo\n    if (ci and ci.lastcastid == act.id and ci.timesincecast < now - hb.pendingAt)\n        or (act.isoncd and not hb.pendingWasOnCD) then\n        hb.pendingID = 0\n        hb.idx = hb.idx + 1\n        hb.nextAt = now + 250\n        return\n    end\n    -- 单步超时 2 秒（读条技能可用 queue.stepTimeout 放宽）\n    if now - hb.pendingAt > (hb.queue.stepTimeout or 2000) then\n        hb:stop()\n        return\n    end\n    hb.nextAt = now + 100\n    return act, tid, hb.ignoreWeave, hb.allowInterrupt\nend\n\nif not act:IsReady(tid) then\n    hb.nextAt = now + 100\n    return\nend\n\nhb.pendingID = act.id\nhb.pendingAt = now\nhb.pendingWasOnCD = act.isoncd\nhb.nextAt = now + 100\nreturn act, tid, hb.ignoreWeave, hb.allowInterrupt\n",
						gVar = "ACR_RikuGNB3_CD",
						name = "Mits Queue Executor",
						uuid = "73c11531-015c-89dd-8f2c-678d6b221fb7",
