	{
		data = 
		{
			actions = 
			{
				
				{
					data = 
					{
						aType = "Lua",
						actionLua = "-- [ForCasual] TargetSelector UI (OnDraw)\n-- 紧凑面板：开关 + 模式 + 实时状态（锁定目标 / 手动暂停 / 漏怪数），展开后可调全部参数\n-- 配置与逻辑共用 data._casual；修改后在松开鼠标时才写盘，窗口位置在拖动结束后保存\n\nlocal SAVE_DIR = [[TensorReactions\\GeneralReactions\\Rikuduo_s_Gadgets\\Settings\\]]\nlocal SAVE_REL = SAVE_DIR .. [[CasualSelector.lua]]\n\n-- ---------- 配置读写（UI 与逻辑共用，谁先运行谁初始化） ----------\nif data._casual_io == nil or data._casual_io.version ~= 3 then\n    local t = { version = 3 }\n    t.DEFAULTS = {\n        enabled = true, scene = \"Auto\", radius = 15,\n        hotkey_vk = 0, mod_shift = false, mod_ctrl = false, mod_alt = false,\n        manual_pause = 4, cooldown = 0.4, margin = 15, sticky = 20,\n        pull_idle = false, respect_friendly = true, draw_markers = true,\n        grab_fresh = true, require_stance = true, other_tank = true, combo_lock = true,\n        win = { x = 200, y = 300 },\n    }\n\n    function t.save(cfg)\n        local base = GetLuaModsPath()\n        if not FolderExists(base .. SAVE_DIR) then FolderCreate(base .. SAVE_DIR) end\n        FileSave(base .. SAVE_REL, cfg)\n    end\n\n    function t.loadCfg()\n        local path = GetLuaModsPath() .. SAVE_REL\n        local cfg = FileExists(path) and FileLoad(path) or nil\n        if type(cfg) ~= \"table\" then cfg = {} end\n        for k, v in pairs(t.DEFAULTS) do\n            if cfg[k] == nil or type(cfg[k]) ~= type(v) then\n                cfg[k] = type(v) == \"table\" and { x = v.x, y = v.y } or v\n            end\n        end\n        if cfg.scene ~= \"Tank\" and cfg.scene ~= \"Other\" then cfg.scene = \"Auto\" end\n        cfg.radius = math.max(1, math.min(50, cfg.radius))\n        return cfg\n    end\n\n    data._casual_io = t\n    data._casual = nil -- 配置结构升级：重新加载，补齐新增项\nend\nlocal cio = data._casual_io\n\ndata._casual = data._casual or cio.loadCfg()\nlocal cfg = data._casual\nlocal st = data._casual_state\n\ndata._casual_ui = data._casual_ui or {\n    menu = false, dirty = false,\n    modeKeys = { \"Auto\", \"Tank\", \"Other\" },\n}\nlocal ui = data._casual_ui\n-- Labels live in their own key so tables cached by an older version get replaced\nif ui.modeLabels == nil then ui.modeLabels = { \"Auto (by job)\", \"Tank\", \"DPS\" } end\n-- Toggle button shows the current mode; \"###\" keeps the button ID stable while the text changes\nif ui.btnLabels == nil then\n    ui.btnLabels = {\n        AutoTank = \"Auto: Tank###casual_toggle\", AutoOther = \"Auto: DPS###casual_toggle\",\n        TankTank = \"Tank###casual_toggle\", OtherOther = \"DPS###casual_toggle\",\n        TankOther = \"Tank###casual_toggle\", OtherTank = \"DPS###casual_toggle\",\n    }\nend\n\n-- ---------- 外观：与 Rikuduo's Gadget / Role Panel 统一 ----------\n-- 左侧灰色大写标签列 + 右侧控件；绿 = 开 / 已选，灰 = 关 / 未选；控件高 22，圆角 5，窗口圆角 8，无标题栏\nlocal LABEL_W, ROW_W, CELL_H, GAP = 64, 176, 22, 3\nlocal GREEN  = { 0.18, 0.49, 0.31, 1.0 }\nlocal GREENH = { 0.22, 0.58, 0.37, 1.0 }\nlocal GRAY   = { 0.15, 0.16, 0.20, 1.0 }\nlocal GRAYH  = { 0.22, 0.24, 0.29, 1.0 }\nlocal LABEL  = { 0.55, 0.58, 0.63, 1.0 }\nlocal TITLE  = { 0.88, 0.90, 0.93, 1.0 }\nlocal WARN   = { 0.98, 0.75, 0.14, 1.0 }\nlocal INFO   = { 0.24, 0.78, 0.94, 1.0 }\nlocal BAD    = { 0.97, 0.44, 0.44, 1.0 }\nlocal TOTAL  = LABEL_W + ROW_W\n\nlocal function push_btn(on, static)\n    local c = on and GREEN or GRAY\n    local h = static and c or (on and GREENH or GRAYH)\n    GUI:PushStyleColor(GUI.Col_Button,        c[1],c[2],c[3],c[4])\n    GUI:PushStyleColor(GUI.Col_ButtonHovered, h[1],h[2],h[3],h[4])\n    GUI:PushStyleColor(GUI.Col_ButtonActive,  h[1],h[2],h[3],h[4])\nend\n\nlocal function colored(c, text) GUI:TextColored(c[1],c[2],c[3],c[4], text) end\n\nlocal function row_label(text)\n    GUI:AlignFirstTextHeightToWidgets()\n    colored(LABEL, text ~= \"\" and text or \" \")\n    GUI:SameLine(0, 0)\n    GUI:SetCursorPosX(GUI:GetCursorStartPos() + LABEL_W)\nend\n\nlocal function chip(label, id, w, on, tip)\n    push_btn(on, false)\n    local pressed = GUI:Button(label .. \"##\" .. id, w, CELL_H)\n    GUI:PopStyleColor(3)\n    if tip and GUI:IsItemHovered() then GUI:SetTooltip(tip) end\n    return pressed\nend\n\n-- 一行等宽开关：items = { { label, key, tip } }，key 为 cfg 中的布尔字段\nlocal function toggle_row(rowLabel, items)\n    row_label(rowLabel)\n    local n = 2\n    local w = (ROW_W - GAP*(n-1)) / n\n    for i, it in ipairs(items) do\n        if i > 1 then GUI:SameLine(0, GAP) end\n        if chip(it[1], \"casual_t_\" .. it[2], w, cfg[it[2]] == true, it[3]) then\n            cfg[it[2]] = not cfg[it[2]]\n            ui.dirty = true\n        end\n    end\nend\n\n-- 滑条行：标签列 + 整行宽滑条（数值显示在滑条内）\nlocal function slider_row(rowLabel, key, lo, hi, fmt, tip, isInt)\n    row_label(rowLabel)\n    GUI:PushItemWidth(ROW_W)\n    local v, c\n    if isInt then\n        v, c = GUI:SliderInt(\"##casual_s_\" .. key, cfg[key], lo, hi, fmt)\n    else\n        v, c = GUI:SliderFloat(\"##casual_s_\" .. key, cfg[key], lo, hi, fmt)\n    end\n    GUI:PopItemWidth()\n    if tip and GUI:IsItemHovered() then GUI:SetTooltip(tip) end\n    if c then cfg[key] = v; ui.dirty = true end\nend\n\nGUI:PushStyleVar(GUI.StyleVar_WindowRounding, 8)\nGUI:PushStyleVar(GUI.StyleVar_FrameRounding, 5)\nGUI:PushStyleVar(GUI.StyleVar_GrabRounding, 4)\nGUI:PushStyleVar(GUI.StyleVar_WindowPadding, 10, 8)\nGUI:PushStyleVar(GUI.StyleVar_ItemSpacing, GAP, GAP)\nGUI:PushStyleColor(GUI.Col_FrameBg,          GRAY[1],GRAY[2],GRAY[3],GRAY[4])\nGUI:PushStyleColor(GUI.Col_FrameBgHovered,   GRAYH[1],GRAYH[2],GRAYH[3],GRAYH[4])\nGUI:PushStyleColor(GUI.Col_FrameBgActive,    GRAYH[1],GRAYH[2],GRAYH[3],GRAYH[4])\nGUI:PushStyleColor(GUI.Col_SliderGrab,       GREEN[1],GREEN[2],GREEN[3],GREEN[4])\nGUI:PushStyleColor(GUI.Col_SliderGrabActive, GREENH[1],GREENH[2],GREENH[3],GREENH[4])\n\nlocal flags = GUI.WindowFlags_AlwaysAutoResize | GUI.WindowFlags_NoScrollbar | GUI.WindowFlags_NoTitleBar | GUI.WindowFlags_NoCollapse\nGUI:SetNextWindowPos(cfg.win.x, cfg.win.y, GUI.SetCond_Once)\nlocal visible = GUI:Begin(\"Casual Auto Selector##casual_ui\", true, flags)\nif visible then\n    local padY = math.max(0, (CELL_H - GUI:GetTextLineHeight()) / 2)\n    GUI:PushStyleVar(GUI.StyleVar_FramePadding, 6, padY)\n\n    -- ---- 折叠时保持小巧：[开关 · 当前模式] [箭头]，下面一两行状态（无标题、无标签列） ----\n    -- Auto 按逻辑上次评估的结果显示实际身份（逻辑还没跑过时按 DPS）\n    local effective = (st and st.mode) or \"Other\"\n    if cfg.scene ~= \"Auto\" then effective = cfg.scene end\n    local modeText = (effective == \"Tank\") and \"Tank\" or \"DPS\"\n    if cfg.scene == \"Auto\" then modeText = \"Auto: \" .. modeText end\n    local toggleText = cfg.enabled and modeText or (modeText .. \" (off)\")\n    local toggleW = GUI:CalcTextSize(toggleText) + 16\n    if chip(toggleText, \"casual_toggle\", toggleW, cfg.enabled,\n            cfg.enabled and \"Auto target: on - click to turn off\" or \"Auto target: off - click to turn on\") then\n        cfg.enabled = not cfg.enabled\n        ui.dirty = true\n    end\n    GUI:SameLine(0, GAP)\n    push_btn(ui.menu, false)\n    if GUI:ArrowButton(\"##casual_menu\", ui.menu and GUI.Dir_Up or GUI.Dir_Down) then\n        ui.menu = not ui.menu\n    end\n    GUI:PopStyleColor(3)\n    if GUI:IsItemHovered() then GUI:SetTooltip(ui.menu and \"Hide settings\" or \"Settings\") end\n\n    -- ---- 状态 ----\n    local stale = not st or Now() - st.lastTick > 1000\n    if not cfg.enabled then\n        colored(LABEL, \"Disabled\")\n    elseif stale then\n        colored(WARN, \"Logic not running\")\n        if GUI:IsItemHovered() then GUI:SetTooltip(\"TargetSelector Logic is not ticking - bot stopped or reaction disabled?\") end\n    else\n        if st.state == \"manual\" then\n            colored(WARN, string.format(\"Paused %.1fs (click)\", math.max(0, st.manualUntil - Now()) / 1000))\n            if GUI:IsItemHovered() then GUI:SetTooltip(\"You picked a target manually. Click to resume now.\") end\n            if GUI:IsItemClicked(0) then st.manualUntil = 0; st.nextEval = 0 end\n        elseif st.state == \"friendly\" then\n            colored(WARN, \"Friendly target, paused\")\n        elseif st.state == \"locked\" then\n            local t = TensorCore.mGetTarget()\n            if t then\n                colored(INFO, string.format(\"→ %s  %d%%\", t.name or \"?\", math.floor(t.hp and t.hp.percent or 0)))\n            else\n                colored(LABEL, \"No valid target nearby\")\n            end\n        else\n            colored(LABEL, \"No valid target nearby\")\n        end\n        if st.mode == \"Tank\" and st.loose > 0 then\n            colored(BAD, string.format(\"Loose %d\", st.loose))\n            GUI:SameLine(0, 10)\n        end\n        colored(LABEL, string.format(\"%dy | %d candidates\", cfg.radius, st.candidates))\n    end\n\n    -- ---- 展开设置 ----\n    if ui.menu then\n        GUI:Separator()\n        row_label(\"MODE\")\n        local segW = (ROW_W - GAP*2) / 3\n        local modes = {\n            { \"Auto\", \"Auto\", \"By job / stance\" },\n            { \"Tank\", \"Tank\", \"Always treat me as tank\" },\n            { \"Other\", \"DPS\", \"Always treat me as DPS\" },\n        }\n        for i, m in ipairs(modes) do\n            if i > 1 then GUI:SameLine(0, GAP) end\n            if chip(m[2], \"casual_mode_\" .. m[1], segW, cfg.scene == m[1], m[3]) and cfg.scene ~= m[1] then\n                cfg.scene = m[1]\n                ui.dirty = true\n            end\n        end\n        slider_row(\"RADIUS\", \"radius\", 1, 50, \"%d y\", nil, true)\n        slider_row(\"PAUSE\", \"manual_pause\", 0, 15, \"%.1f s\",\n            \"After you pick a target manually, auto-select stays off for this long. 0 = never pause.\")\n        slider_row(\"COOLDOWN\", \"cooldown\", 0, 3, \"%.2f s\",\n            \"Minimum time between automatic switches. Urgent targets (loose / fresh adds, interruptible casts) ignore it.\")\n        slider_row(\"MARGIN\", \"margin\", 0, 100, \"%.0f\",\n            \"A new target must score this much higher than the current one. Higher = less target hopping. Halved when the current target is out of reach.\")\n        slider_row(\"STICKY\", \"sticky\", 0, 100, \"%.0f\", \"Score bonus for keeping the current target.\")\n\n        GUI:Separator()\n        toggle_row(\"TANK\", {\n            { \"Idle enemies\", \"pull_idle\", \"Tank: allow idle (unpulled) enemies\" },\n            { \"Fresh adds\", \"grab_fresh\", \"While you are in combat, enemies that appeared within the last 6s and have no target yet are treated as new adds and picked up immediately.\" },\n        })\n        toggle_row(\"\", {\n            { \"Combo hold\", \"combo_lock\", \"Don't switch mid-combo unless something urgent appears (loose / fresh add, interruptible cast).\" },\n            { \"Need stance\", \"require_stance\", \"Auto mode and party roles: a tank without stance is treated as DPS.\" },\n        })\n        toggle_row(\"DPS\", {\n            { \"Other tanks\", \"other_tank\", \"DPS: follow other tanks if ours has none\" },\n            { \"Friendly pause\", \"respect_friendly\", \"Pause while targeting a friendly\" },\n        })\n        toggle_row(\"DRAW\", {\n            { \"Aggro rings\", \"draw_markers\", \"Thin rings under in-combat enemies in range: red = on you, yellow = on a party member, gray = other.\" },\n        })\n\n        GUI:Separator()\n        -- 热键：VK 码 + 清除；下一行修饰键\n        row_label(\"HOTKEY\")\n        local clearW = 48\n        GUI:PushItemWidth(ROW_W - clearW - GAP)\n        local v, c = GUI:InputInt(\"##casual_vk\", cfg.hotkey_vk, 1, 10)\n        GUI:PopItemWidth()\n        if GUI:IsItemHovered() then GUI:SetTooltip(\"Windows virtual-key code, 0 = no hotkey\") end\n        if c then cfg.hotkey_vk = math.max(0, math.floor(v or 0)); ui.dirty = true end\n        GUI:SameLine(0, GAP)\n        if chip(\"Clear\", \"casual_vk_clear\", clearW, false) then cfg.hotkey_vk = 0; ui.dirty = true end\n        row_label(\"\")\n        local modW = (ROW_W - GAP*2) / 3\n        for i, m in ipairs({ { \"Shift\", \"mod_shift\" }, { \"Ctrl\", \"mod_ctrl\" }, { \"Alt\", \"mod_alt\" } }) do\n            if i > 1 then GUI:SameLine(0, GAP) end\n            if chip(m[1], \"casual_\" .. m[2], modW, cfg[m[2]] == true) then\n                cfg[m[2]] = not cfg[m[2]]\n                ui.dirty = true\n            end\n        end\n\n        GUI:Separator()\n        row_label(\"\")\n        if chip(\"Restore defaults\", \"casual_defaults\", ROW_W, false, \"Reset every setting except the hotkey\") then\n            local d = cio.DEFAULTS\n            cfg.scene, cfg.radius = d.scene, d.radius\n            cfg.manual_pause, cfg.cooldown, cfg.margin, cfg.sticky = d.manual_pause, d.cooldown, d.margin, d.sticky\n            cfg.pull_idle, cfg.respect_friendly, cfg.draw_markers = d.pull_idle, d.respect_friendly, d.draw_markers\n            cfg.grab_fresh, cfg.require_stance, cfg.other_tank, cfg.combo_lock = d.grab_fresh, d.require_stance, d.other_tank, d.combo_lock\n            ui.dirty = true\n        end\n    end\n\n    -- 展开时固定宽度；折叠时按内容收缩\n    if ui.menu then GUI:Dummy(TOTAL, 0) end\n    GUI:PopStyleVar() -- FramePadding\n\n    -- ---- 位置：拖动结束后记录 ----\n    local wx, wy = GUI:GetWindowPos()\n    if (wx ~= cfg.win.x or wy ~= cfg.win.y) and not GUI:IsMouseDown(0) then\n        cfg.win.x, cfg.win.y = wx, wy\n        ui.dirty = true\n    end\nend\nGUI:End()\nGUI:PopStyleColor(5)\nGUI:PopStyleVar(5)\n\n-- 拖动滑块时不反复写盘：松开鼠标后统一保存\nif ui.dirty and not GUI:IsMouseDown(0) then\n    ui.dirty = false\n    cio.save(cfg)\nend\n\nself.used = true\n",
