	{
		data = 
		{
			actions = 
			{
				
				{
					data = 
					{
						aType = "Lua",
						actionLua = "-- [ForCasual] TargetSelector Logic (OnFrame)  v3 — 评分规则与 I-Ching AutoTargetSelector 对齐\n-- 坦克：漏怪（打奶妈 200 / 打队友 150，越近越优先，够得着 +20）> 战斗中新刷出的怪（130）> 自己身上的怪\n--       （残血、集火、精英、怪群中心；够不着 -15）；够得着的可打断读条 +200；副 T 的怪不抢\n-- 输出：坦克身上 200 / 队友身上 100 / 本队坦克没拉到怪时跟其他坦克 150；残血、集火加分，够不着大幅扣分；绝不拉怪\n-- 紧急目标（漏怪 / 新怪 / 可打断读条）无视切换冷却与连击锁；坦克连击中不换目标\n-- 当前目标跑出够得着的范围、而最佳目标就在身边时，切换阈值减半\n-- 手动选中后暂停接管；当前目标合格时保持（粘性）。战斗中 100ms 评估一次，脱战 150ms；标记每帧绘制\n-- 配置与 UI 共用 data._casual，状态写入 data._casual_state\n\nlocal SAVE_DIR = [[TensorReactions\\GeneralReactions\\Rikuduo_s_Gadgets\\Settings\\]]\nlocal SAVE_REL = SAVE_DIR .. [[CasualSelector.lua]]\n\n-- ---------- 配置读写（UI 与逻辑共用，谁先运行谁初始化） ----------\nif data._casual_io == nil or data._casual_io.version ~= 3 then\n    local t = { version = 3 }\n    t.DEFAULTS = {\n        enabled = true, scene = \"Auto\", radius = 15,\n        hotkey_vk = 0, mod_shift = false, mod_ctrl = false, mod_alt = false,\n        manual_pause = 4, cooldown = 0.4, margin = 15, sticky = 20,\n        pull_idle = false, respect_friendly = true, draw_markers = true,\n        grab_fresh = true, require_stance = true, other_tank = true, combo_lock = true,\n        win = { x = 200, y = 300 },\n    }\n\n    function t.save(cfg)\n        local base = GetLuaModsPath()\n        if not FolderExists(base .. SAVE_DIR) then FolderCreate(base .. SAVE_DIR) end\n        FileSave(base .. SAVE_REL, cfg)\n    end\n\n    function t.loadCfg()\n        local path = GetLuaModsPath() .. SAVE_REL\n        local cfg = FileExists(path) and FileLoad(path) or nil\n        if type(cfg) ~= \"table\" then cfg = {} end\n        for k, v in pairs(t.DEFAULTS) do\n            if cfg[k] == nil or type(cfg[k]) ~= type(v) then\n                cfg[k] = type(v) == \"table\" and { x = v.x, y = v.y } or v\n            end\n        end\n        if cfg.scene ~= \"Tank\" and cfg.scene ~= \"Other\" then cfg.scene = \"Auto\" end\n        cfg.radius = math.max(1, math.min(50, cfg.radius))\n        return cfg\n    end\n\n    data._casual_io = t\n    data._casual = nil -- 配置结构升级：重新加载，补齐新增项\nend\nlocal cio = data._casual_io\n\n-- ---------- 逻辑辅助（每次 data 重置或版本升级后初始化一次） ----------\nif data._casual_fn == nil or data._casual_fn.version ~= 3 then\n    local fn = { version = 3 }\n    fn.TANK = { [1] = true, [3] = true, [19] = true, [21] = true, [32] = true, [37] = true }\n    fn.HEALER = { [6] = true, [24] = true, [28] = true, [33] = true, [40] = true }\n    -- 近战（够得着 = 3y，其余 25y）：剑 / 格斗 / 斧 / 枪 / 双剑 及其职业，暗骑 / 武士 / 绝枪 / 钐镰 / 蝰蛇\n    fn.MELEE = {\n        [1] = true, [2] = true, [3] = true, [4] = true, [19] = true, [20] = true, [21] = true, [22] = true,\n        [29] = true, [30] = true, [32] = true, [34] = true, [37] = true, [39] = true, [41] = true,\n    }\n    fn.FRESH_MS = 6000\n\n    -- 盾姿：钢铁信念 79/393/2843、守护 91/3124、深恶痛绝 743、王室亲卫 1833/392\n    function fn.stanced(ent)\n        return TensorCore.hasAnyBuff(ent, 79, 393, 2843, 91, 3124, 743, 1833, 392)\n    end\n\n    -- 坦克职业，且（要求盾姿时）开着盾姿\n    function fn.isTank(ent, job, cfg)\n        if not fn.TANK[job] then return false end\n        return not cfg.require_stance or fn.stanced(ent)\n    end\n\n    -- 队伍角色缓存：id -> \"tank\" / \"healer\" / \"member\"；没开盾姿的坦克按 member 算\n    function fn.refreshParty(st, me, cfg)\n        local party, ids = st.party, st.partyIds\n        for k in pairs(party) do party[k] = nil end\n        local n = 0\n        local list = TensorCore.getEntityGroupList(\"Party\")\n        if list then\n            for _, e in pairs(list) do\n                if e.id ~= me.id then\n                    party[e.id] = fn.isTank(e.id, e.job, cfg) and \"tank\" or fn.HEALER[e.job] and \"healer\" or \"member\"\n                    n = n + 1\n                    ids[n] = e.id\n                end\n            end\n        end\n        for i = n + 1, #ids do ids[i] = nil end\n    end\n\n    function fn.holderRole(st, me, holder)\n        if holder == 0 then return nil end\n        if holder == me.id then return \"me\" end\n        local r = st.party[holder]\n        if r then return r end\n        -- 宠物 / 陆行鸟 / 召唤物：主人是自己或队友时算“打队友”\n        local h = TensorCore.mGetEntity(holder)\n        if h and h.ownerid and h.ownerid ~= 0 and (h.ownerid == me.id or st.party[h.ownerid]) then\n            return \"member\"\n        end\n        return \"other\"\n    end\n\n    -- 队外坦克（团队 / 路人）：本队坦克没拉到怪时，输出跟他打\n    function fn.isOtherTank(holder, cfg)\n        local h = TensorCore.mGetEntity(holder)\n        return h ~= nil and h.alive and not h.attackable and fn.isTank(holder, h.job, cfg)\n    end\n\n    -- forEachEntity 回调：只收集 ID，评分在主体里做（需要两遍：先统计精英 / 怪群中心 / 本队坦克是否拉到怪）\n    function fn.collect(id, st)\n        local n = st.n + 1\n        st.n = n\n        st.ids[n] = id\n        return true\n    end\n\n    -- 记录每个敌人第一次出现的时间（判定战斗中新刷出的怪）\n    function fn.firstSeen(st, id, now)\n        local t = st.seen[id]\n        if t == nil then\n            st.seen[id] = now\n            st.seenCount = st.seenCount + 1\n            return now\n        end\n        return t\n    end\n\n    function fn.pruneSeen(st, me, now)\n        local map = me.localmapid or 0\n        if map ~= st.seenMap then\n            st.seen, st.seenCount, st.seenMap, st.seenWarm = {}, 0, map, false\n            return\n        end\n        if st.seenCount < 128 then return end\n        local n = 0\n        for k, v in pairs(st.seen) do\n            if now - v > 60000 then st.seen[k] = nil else n = n + 1 end\n        end\n        st.seenCount = n\n    end\n\n    function fn.evaluate(st, me, cfg, now)\n        local reach = fn.MELEE[me.job] and 3 or 25\n        st.reach = reach\n        local radius = cfg.radius\n        local tank = st.tank\n        local meStanced = fn.TANK[me.job] and fn.stanced(me) or false\n\n        -- 队友集火：队员（含亲信）正在打的目标\n        local focus = st.focus\n        for k in pairs(focus) do focus[k] = nil end\n        for i = 1, #st.partyIds do\n            local p = TensorCore.mGetEntity(st.partyIds[i])\n            if p and p.alive and p.targetid and p.targetid ~= 0 then\n                focus[p.targetid] = (focus[p.targetid] or 0) + 1\n            end\n        end\n\n        st.n = 0\n        TensorCore.forEachEntity(st.filter, fn.collect, st)\n        fn.pruneSeen(st, me, now)\n\n        -- 第一遍：缓存实体、记录首次出现时间；统计精英血量上限 / 自己身上怪群中心 / 本队坦克是否拉到怪\n        local ents, n = st.ents, 0\n        local topMaxHp, packX, packZ, packCount, ownTankHolds = 1, 0, 0, 0, false\n        for i = 1, st.n do\n            local id = st.ids[i]\n            local e = TensorCore.mGetEntity(id)\n            if e and e.alive and e.attackable then\n                local seenAt = fn.firstSeen(st, id, now) -- 不论远近都记录：早就在场的怪不会被误当成新怪\n                if (e.distance2d or 999) <= radius then\n                    n = n + 1\n                    ents[n] = e\n                    st.entSeen[n] = seenAt\n                    local holder = e.targetid or 0\n                    if tank then\n                        local mx = e.hp and e.hp.max or 1\n                        if mx > topMaxHp then topMaxHp = mx end\n                        if holder == me.id and e.pos then\n                            packX, packZ, packCount = packX + e.pos.x, packZ + e.pos.z, packCount + 1\n                        end\n                    elseif holder ~= 0 and not ownTankHolds then\n                        if st.party[holder] == \"tank\" or (holder == me.id and meStanced) then ownTankHolds = true end\n                    end\n                end\n            end\n        end\n        for i = n + 1, #ents do ents[i] = nil end\n        if packCount > 0 then packX, packZ = packX / packCount, packZ / packCount end\n        local otherTankOk = not tank and cfg.other_tank and not ownTankHolds\n        local inDutyCombat = me.incombat and cfg.grab_fresh and st.seenWarm\n\n        local curId = st.curId\n        local bestId, bestScore, bestUrgent, bestDist = 0, -math.huge, false, 0\n        local curScore, candidates, loose, marks = nil, 0, 0, 0\n\n        -- 第二遍：评分\n        for i = 1, n do\n            local e = ents[i]\n            local id = e.id\n            local dist = math.max(0, e.distance2d or 999) -- distance2d 已是圈边缘到圈边缘的距离\n            local hp = e.hp and e.hp.percent or 100\n            local holder = e.targetid or 0\n            local role = fn.holderRole(st, me, holder)\n            local inCombat = e.incombat or holder ~= 0\n            if inCombat then\n                marks = marks + 1\n                st.markIds[marks] = id\n                st.markKind[marks] = role == \"me\" and 1 or (role == \"tank\" or role == \"healer\" or role == \"member\") and 2 or 3\n            end\n            local score, urgent = nil, false\n\n            if tank then\n                if role == \"me\" then\n                    score = 10 + (100 - hp) * 0.2                                 -- 自己身上：残血优先\n                    if dist > reach then score = score - 15 end\n                    score = score + math.min(focus[id] or 0, 4) * 8               -- 跟队友集火（最多 +32）\n                    score = score + 10 * (e.hp and e.hp.max or 0) / topMaxHp      -- 精英（血量上限高）优先\n                    if packCount >= 3 and e.pos then                              -- 怪群：选靠中间的，AoE 扫到最多\n                        local dx, dz = e.pos.x - packX, e.pos.z - packZ\n                        score = score + 10 * (1 - math.min(math.sqrt(dx * dx + dz * dz), 8) / 8)\n                    end\n                elseif role == \"tank\" then\n                    score = nil                                                   -- 副 T 的怪不抢\n                elseif role == \"healer\" or role == \"member\" then\n                    score = (role == \"healer\" and 200 or 150) - dist * 2          -- 漏怪：打奶妈最急，越近越优先\n                    if dist <= reach then score = score + 20 end\n                    loose = loose + 1\n                    urgent = true\n                elseif not inCombat and not (inDutyCombat and holder == 0 and now - st.entSeen[i] < fn.FRESH_MS) then\n                    if cfg.pull_idle then score = 30 - dist * 2 end               -- 允许拉怪：未开怪的就近\n                elseif holder == 0 then\n                    score = 130 - dist * 2 + 10 * (e.hp and e.hp.max or 0) / topMaxHp -- 战斗中新刷出 / 没人拉住的怪\n                    urgent = true\n                else\n                    score = 20 - dist * 2                                         -- 打队外玩家的怪\n                end\n\n                -- 够得着的可打断读条：临时顶上来方便插言 / 下踢\n                local ci = score and e.castinginfo\n                if ci and ci.castinginterruptible and (ci.castingid or 0) ~= 0 and dist <= reach then\n                    local remain = (ci.channelingid or 0) ~= 0 and (ci.casttime or 0) - (ci.channeltime or 0) or 1\n                    if remain > 0.3 then\n                        score = score + 200\n                        urgent = true\n                    end\n                end\n            elseif inCombat then\n                if role == \"tank\" or (role == \"me\" and meStanced) then\n                    score = 200                                                   -- 坦克身上\n                elseif role == \"me\" or role == \"healer\" or role == \"member\" then\n                    score = 100                                                   -- 打队友 / 自己\n                elseif otherTankOk and holder ~= 0 and fn.isOtherTank(holder, cfg) then\n                    score = 150                                                   -- 本队坦克没拉到怪：跟其他坦克打\n                end\n                if score then\n                    score = score + (100 - hp) + math.min(focus[id] or 0, 4) * 25\n                    if dist > reach then score = score - 120 - (dist - reach) * 5 end -- 够不着：先打身边的\n                end\n            end\n\n            if score then\n                candidates = candidates + 1\n                if id == curId then\n                    score = score + cfg.sticky\n                    curScore = score\n                end\n                if score > bestScore then\n                    bestId, bestScore, bestUrgent, bestDist = id, score, urgent, dist\n                end\n            end\n        end\n\n        st.seenWarm = true\n        st.curScore, st.bestId, st.bestScore, st.bestUrgent, st.bestDist = curScore, bestId, bestScore, bestUrgent, bestDist\n        st.candidates, st.loose, st.marks = candidates, tank and loose or 0, marks\n    end\n\n    -- Same look as [ForCasual] Highlight Attackable: red = on me, yellow = on party, gray = other\n    fn.drawers = {\n        TensorCore.getStaticDrawer(GUI:ColorConvertFloat4ToU32(1, 0.2, 0.2, 1), 1.5),\n        TensorCore.getStaticDrawer(GUI:ColorConvertFloat4ToU32(1, 1, 0.2, 1), 1.5),\n        TensorCore.getStaticDrawer(GUI:ColorConvertFloat4ToU32(0.5, 0.5, 0.5, 1), 1.5),\n    }\n    function fn.drawRing(id, kind)\n        local e = TensorCore.mGetEntity(id)\n        if not e or not e.pos then return end\n        local hr = e.hitradius or 1\n        fn.drawers[kind]:addDonut(e.pos.x, e.pos.y, e.pos.z, hr - 0.05, hr, false)\n    end\n    data._casual_fn = fn\nend\nlocal fn = data._casual_fn\n\ndata._casual = data._casual or cio.loadCfg()\nlocal cfg = data._casual\n\nif data._casual_state == nil or data._casual_state.version ~= 3 then\n    data._casual_state = {\n        version = 3,\n        party = {}, partyIds = {}, focus = {}, ids = {}, ents = {}, entSeen = {}, n = 0,\n        seen = {}, seenCount = 0, seenMap = -1, seenWarm = false,\n        markIds = {}, markKind = {}, marks = 0,\n        nextEval = 0, nextParty = 0, lastSwitch = 0, manualUntil = 0, lastAutoId = 0, hkPrev = false,\n        filter = \"alive,attackable,maxdistance=50\", reach = 3,\n        state = \"off\", mode = \"Other\", loose = 0, candidates = 0, lastTick = 0,\n        curId = 0, bestId = 0, bestScore = 0, bestUrgent = false, bestDist = 0,\n    }\nend\nlocal st = data._casual_state\nlocal now = Now()\nst.lastTick = now\n\n-- ---------- 热键：上升沿切换开关 ----------\nif cfg.hotkey_vk ~= 0 then\n    local down = GUI:IsKeyDown(cfg.hotkey_vk)\n        and (not cfg.mod_shift or GUI:IsKeyDown(16))\n        and (not cfg.mod_ctrl or GUI:IsKeyDown(17))\n        and (not cfg.mod_alt or GUI:IsKeyDown(18))\n    if down and not st.hkPrev then\n        cfg.enabled = not cfg.enabled\n        cio.save(cfg)\n    end\n    st.hkPrev = down\nend\n\nif not cfg.enabled then\n    st.state = \"off\"\n    st.loose = 0\n    st.marks = 0\n    self.used = true\n    return\nend\n\nlocal me = TensorCore.mGetPlayer()\nif not me or not me.id then\n    self.used = true\n    return\nend\n\n-- ---------- 评估（战斗中 100ms，脱战 150ms） ----------\nif now >= st.nextEval then\n    st.nextEval = now + (me.incombat and 100 or 150)\n    if now >= st.nextParty then\n        fn.refreshParty(st, me, cfg)\n        st.nextParty = now + 1000\n    end\n\n    -- 自动模式：开着盾姿的坦克按坦克处理，没开盾姿的坦克按输出处理\n    st.tank = cfg.scene == \"Tank\" or (cfg.scene == \"Auto\" and fn.isTank(me, me.job, cfg))\n    st.mode = st.tank and \"Tank\" or \"Other\"\n\n    local target = TensorCore.mGetTarget()\n    local curId = target and target.id or 0\n    -- 当前目标不是脚本最后设置的 → 用户手动切换，暂停接管\n    if curId ~= 0 and curId ~= st.lastAutoId then\n        st.manualUntil = now + cfg.manual_pause * 1000\n        st.lastAutoId = curId\n    end\n\n    st.curId = curId\n    fn.evaluate(st, me, cfg, now)\n\n    if now < st.manualUntil then\n        st.state = \"manual\"\n    elseif cfg.respect_friendly and target and not target.attackable then\n        st.state = \"friendly\"\n    elseif st.bestId == 0 then\n        st.state = st.curScore and \"locked\" or \"waiting\"\n    else\n        local margin = cfg.margin\n        if target and (target.distance2d or 0) > st.reach and st.bestDist <= st.reach then\n            margin = margin * 0.5 -- 当前目标跑出够得着的范围：更容易换到身边的\n        end\n        local switch = st.curScore == nil\n            or (st.bestId ~= curId and st.bestScore > st.curScore + margin)\n        -- 坦克连击中不换目标，除非有漏怪 / 新怪 / 可打断读条\n        if switch and st.tank and cfg.combo_lock and not st.bestUrgent and st.curScore\n            and (me.lastcomboid or 0) ~= 0 and (me.combotimeremain or 0) > 0 then\n            switch = false\n        end\n        if switch and st.bestId ~= curId and (st.bestUrgent or now - st.lastSwitch >= cfg.cooldown * 1000) then\n            Player:SetTarget(st.bestId)\n            st.lastAutoId = st.bestId\n            st.lastSwitch = now\n        end\n        st.state = \"locked\"\n    end\nend\n\n-- ---------- 标记（每帧） ----------\nif cfg.draw_markers then\n    for i = 1, st.marks do\n        fn.drawRing(st.markIds[i], st.markKind[i])\n    end\nend\n\nself.used = true\n",
